export default StaffCollectionQueue;

import React, { useState, useEffect } from 'react';
import { Search, Wallet, Calendar, User, Phone, CheckCircle, CreditCard, ArrowRight, Clock, FileText, AlertCircle, RefreshCw } from 'lucide-react';
import { useGetPendingCollectionsQuery, useSubmitPaymentCollectionMutation } from '../../../../store/api/accountsApi';
import { useAppSelector } from '../../../../store/hooks';
import { selectUser } from '../../../../store/slices/authSlice';

const MyCollections = ({ search: parentSearch, setSearch: parentSetSearch }) => {
    const user = useAppSelector(selectUser);
    const [projects, setProjects] = useState([]);

    const [localSearch, setLocalSearch] = useState('');
    const search = parentSearch !== undefined ? parentSearch : localSearch;
    const setSearch = parentSetSearch !== undefined ? parentSetSearch : setLocalSearch;
    const [collectingProject, setCollectingProject] = useState(null);

    // Modal Form State
    const [formData, setFormData] = useState({
        collectedAmount: '',
        paymentMode: 'Bank Transfer',
        referenceNumber: '',
        paymentNotes: ''
    });
    const [submitting, setSubmitting] = useState(false);

    const { data: res, isLoading: loading, refetch: fetchData } = useGetPendingCollectionsQuery();
    const [submitPaymentCollection] = useSubmitPaymentCollectionMutation();

    useEffect(() => {
        if (res?.success) {
            // Filter projects assigned to this logged in staff
            const assigned = (res.data || []).filter(p => {
                const assignedStaff = p.assignedAccountsStaff;
                if (!assignedStaff) return false;

                const assignedStaffId = assignedStaff._id || assignedStaff;
                const loggedInUserId = user?._id || user?.id;

                // 1. Match by user ID
                if (loggedInUserId && assignedStaffId === loggedInUserId) return true;

                // 2. Fallback to match by email
                const assignedEmail = assignedStaff.email;
                const loggedInEmail = user?.email;
                if (assignedEmail && loggedInEmail && assignedEmail.toLowerCase() === loggedInEmail.toLowerCase()) return true;

                // 3. Fallback to match by staffId
                const assignedStaffIdVal = assignedStaff.staffId;
                const loggedInStaffIdVal = user?.staffId;
                if (assignedStaffIdVal && loggedInStaffIdVal && assignedStaffIdVal === loggedInStaffIdVal) return true;

                return false;
            });
            setProjects(assigned);
        }
    }, [res, user]);

    const handleOpenCollect = (project) => {
        const isBal = project.paymentStatus !== 'Pending Advance';
        const targetAmount = isBal ? (project.budget - (project.advanceAmount || project.collectedAmount || 0)) : (project.advanceAmount || 0);

        setCollectingProject(project);
        setFormData({
            collectedAmount: targetAmount || '',
            paymentMode: 'Bank Transfer',
            referenceNumber: '',
            paymentNotes: ''
        });
    };

    const handleSubmitCollection = async (e) => {
        e.preventDefault();
        if (!formData.collectedAmount || Number(formData.collectedAmount) <= 0) {
            return alert('Please enter a valid collected amount.');
        }

        try {
            setSubmitting(true);
            const res = await submitPaymentCollection({
                projectId: collectingProject._id,
                collectedAmount: Number(formData.collectedAmount),
                paymentMode: formData.paymentMode,
                referenceNumber: formData.referenceNumber,
                paymentNotes: formData.paymentNotes
            }).unwrap();

            if (res?.success) {
                alert('Payment collection details submitted successfully! Assigned Accounts Manager will verify it shortly.');
                setCollectingProject(null);
                fetchData();
            } else {
                alert(res?.message || 'Error recording payment.');
            }
        } catch (err) {
            alert('Failed to submit: ' + err.message);
        } finally {
            setSubmitting(false);
        }
    };

    // Calculate dynamic stats
    const pendingCollections = projects.filter(p => p.paymentCollectionStatus === 'Assigned');
    const collectedCollections = projects.filter(p => p.paymentCollectionStatus === 'Collected');
    const totalPendingAmount = pendingCollections.reduce((acc, p) => {
        const isBal = p.paymentStatus !== 'Pending Advance';
        const target = isBal ? (p.budget - (p.advanceAmount || p.collectedAmount || 0)) : (p.advanceAmount || 0);
        return acc + target;
    }, 0);

    const filtered = projects.filter(p => 
        p.name?.toLowerCase().includes(search.toLowerCase()) || 
        p.client?.name?.toLowerCase().includes(search.toLowerCase()) ||
        p.projectNumber?.toLowerCase().includes(search.toLowerCase())
    );

    return (
        <div style={{ padding: '0 8px' }}>
            {/* Header section with Refresh only (since title is in navbar) */}
            <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '16px' }}>
                <button onClick={fetchData} className="btn-outline" style={{ display: 'flex', alignItems: 'center', gap: '8px', padding: '10px 16px', background: '#fff' }}>
                    <RefreshCw size={15} className={loading ? 'spin-anim' : ''} /> Refresh
                </button>
            </div>

            {/* Stats row */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: '20px', marginBottom: '28px' }}>
                <div style={{ background: '#fff', border: '1px solid #e2e8f0', borderRadius: '12px', padding: '20px', display: 'flex', alignItems: 'center', gap: '16px' }}>
                    <div style={{ width: '48px', height: '48px', borderRadius: '10px', background: 'rgba(99, 102, 241, 0.1)', color: '#6366f1', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        <Wallet size={22} />
                    </div>
                    <div>
                        <div style={{ fontSize: '14px', color: '#64748b', fontWeight: 500 }}>Total Pending Value</div>
                        <div style={{ fontSize: '22px', fontWeight: 700, color: '#0f172a', marginTop: '2px' }}>₹{totalPendingAmount.toLocaleString('en-IN')}</div>
                    </div>
                </div>

                <div style={{ background: '#fff', border: '1px solid #e2e8f0', borderRadius: '12px', padding: '20px', display: 'flex', alignItems: 'center', gap: '16px' }}>
                    <div style={{ width: '48px', height: '48px', borderRadius: '10px', background: 'rgba(245, 158, 11, 0.1)', color: '#f59e0b', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        <Clock size={22} />
                    </div>
                    <div>
                        <div style={{ fontSize: '14px', color: '#64748b', fontWeight: 500 }}>Pending Collections</div>
                        <div style={{ fontSize: '22px', fontWeight: 700, color: '#0f172a', marginTop: '2px' }}>{pendingCollections.length} Tasks</div>
                    </div>
                </div>

                <div style={{ background: '#fff', border: '1px solid #e2e8f0', borderRadius: '12px', padding: '20px', display: 'flex', alignItems: 'center', gap: '16px' }}>
                    <div style={{ width: '48px', height: '48px', borderRadius: '10px', background: 'rgba(16, 185, 129, 0.1)', color: '#10b981', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        <CheckCircle size={22} />
                    </div>
                    <div>
                        <div style={{ fontSize: '14px', color: '#64748b', fontWeight: 500 }}>Awaiting Verification</div>
                        <div style={{ fontSize: '22px', fontWeight: 700, color: '#0f172a', marginTop: '2px' }}>{collectedCollections.length} Projects</div>
                    </div>
                </div>
            </div>

            {/* Filter and Content Card */}
            <div style={{ background: '#fff', border: '1px solid #e2e8f0', borderRadius: '12px', overflow: 'hidden' }}>


                {loading ? (
                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '60px 0' }}>
                        <RefreshCw className="spin-anim" style={{ color: '#6366f1', marginBottom: '12px' }} size={32} />
                        <div style={{ color: '#64748b', fontWeight: 500 }}>Loading assigned collection tasks...</div>
                    </div>
                ) : filtered.length === 0 ? (
                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '80px 0', textClassName: 'text-center' }}>
                        <AlertCircle size={44} style={{ color: '#94a3b8', marginBottom: '16px' }} />
                        <h3 style={{ margin: 0, fontSize: '18px', fontWeight: 600, color: '#1e293b' }}>No Collection Tasks Found</h3>
                        <p style={{ margin: '6px 0 0', color: '#64748b', fontSize: '14px', maxWidth: '360px', textAlign: 'center', lineHeight: 1.5 }}>
                            {search ? "No projects match your current search terms." : "You do not have any active payment collection assignments right now."}
                        </p>
                    </div>
                ) : (
                    <div style={{ padding: '24px', display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(340px, 1fr))', gap: '20px' }}>
                        {filtered.map(p => {
                            const isCollected = p.paymentCollectionStatus === 'Collected';
                            const isBal = p.paymentStatus !== 'Pending Advance';
                            const targetAmount = isBal ? (p.budget - (p.advanceAmount || p.collectedAmount || 0)) : (p.advanceAmount || 0);

                            return (
                                <div key={p._id} style={{ 
                                    border: '1px solid #e2e8f0', 
                                    borderRadius: '12px', 
                                    background: '#fff',
                                    display: 'flex', 
                                    flexDirection: 'column',
                                    transition: 'all 0.2s',
                                    boxShadow: '0 1px 3px 0 rgba(0, 0, 0, 0.05)'
                                }}>
                                    {/* Top status bar */}
                                    <div style={{ 
                                        padding: '12px 18px', 
                                        borderBottom: '1px solid #f1f5f9', 
                                        display: 'flex', 
                                        justifyContent: 'space-between', 
                                        alignItems: 'center',
                                        background: isCollected ? '#f0fdf4' : '#fef3c7',
                                        borderTopLeftRadius: '11px',
                                        borderTopRightRadius: '11px'
                                    }}>
                                        <span style={{ fontSize: '12px', fontWeight: 700, color: '#475569' }}>
                                            {p.projectNumber || 'PROJ'}
                                        </span>
                                        <span style={{ 
                                            display: 'inline-flex',
                                            alignItems: 'center',
                                            gap: '4px',
                                            fontSize: '12px', 
                                            fontWeight: 700, 
                                            color: isCollected ? '#166534' : '#92400e',
                                        }}>
                                            {isCollected ? (
                                                <>
                                                    <CheckCircle size={12} /> Collected
                                                </>
                                            ) : (
                                                <>
                                                    <Clock size={12} /> Pending Collection
                                                </>
                                            )}
                                        </span>
                                    </div>

                                    {/* Details Area */}
                                    <div style={{ padding: '18px', flex: 1, display: 'flex', flexDirection: 'column', gap: '14px' }}>
                                        <div>
                                            <h4 style={{ margin: 0, fontSize: '16px', fontWeight: 700, color: '#0f172a' }}>{p.name}</h4>
                                            <span style={{ fontSize: '12px', color: '#64748b', display: 'block', marginTop: '2px' }}>
                                                Total Budget: ₹{p.budget?.toLocaleString('en-IN')}
                                            </span>
                                        </div>

                                        {/* Client Info Widget */}
                                        <div style={{ background: '#f8fafc', padding: '12px', borderRadius: '8px', border: '1px solid #f1f5f9' }}>
                                            <div style={{ fontSize: '11px', fontWeight: 600, color: '#94a3b8', textTransform: 'uppercase', marginBottom: '6px' }}>CLIENT DETAILS</div>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
                                                <User size={13} style={{ color: '#64748b' }} />
                                                <span style={{ fontSize: '13px', fontWeight: 600, color: '#334155' }}>{p.client?.name || 'Client'}</span>
                                            </div>
                                            {p.client?.phone && (
                                                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                                    <Phone size={13} style={{ color: '#64748b' }} />
                                                    <span style={{ fontSize: '13px', color: '#64748b' }}>{p.client.phone}</span>
                                                </div>
                                            )}
                                        </div>

                                        {/* Target Amount */}
                                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 0', borderTop: '1px dashed #e2e8f0' }}>
                                            <span style={{ fontSize: '13px', color: '#64748b', fontWeight: 500 }}>{isBal ? 'Balance Due:' : 'Advance Due (50%):'}</span>
                                            <span style={{ fontSize: '18px', fontWeight: 800, color: '#6366f1' }}>₹{targetAmount.toLocaleString('en-IN')}</span>
                                        </div>
                                    </div>

                                    {/* Action footer */}
                                    <div style={{ padding: '16px 18px', borderTop: '1px solid #f1f5f9', background: '#f8fafc', borderBottomLeftRadius: '11px', borderBottomRightRadius: '11px' }}>
                                        {isCollected ? (
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#166534', fontSize: '13px', fontWeight: 600, padding: '8px 0', justifyContent: 'center' }}>
                                                <AlertCircle size={15} /> Awaiting Manager Verification
                                            </div>
                                        ) : (
                                            <button 
                                                onClick={() => handleOpenCollect(p)}
                                                style={{ 
                                                    width: '100%', 
                                                    height: '40px',
                                                    display: 'flex', 
                                                    alignItems: 'center', 
                                                    justifyContent: 'center',
                                                    gap: '8px',
                                                    background: '#6366f1',
                                                    color: '#fff',
                                                    border: 'none',
                                                    borderRadius: '8px',
                                                    fontWeight: 600,
                                                    fontSize: '14px',
                                                    cursor: 'pointer',
                                                    transition: 'background 0.2s'
                                                }}
                                                onMouseOver={e => e.currentTarget.style.background = '#4f46e5'}
                                                onMouseOut={e => e.currentTarget.style.background = '#6366f1'}
                                            >
                                                <CreditCard size={15} /> Collect Payment <ArrowRight size={14} />
                                            </button>
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>

            {/* Collection Input Wizard Modal */}
            {collectingProject && (
                <div style={{ 
                    position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, 
                    background: 'rgba(15, 23, 42, 0.6)', backdropFilter: 'blur(4px)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 99999 
                }}>
                    <div style={{ 
                        background: '#fff', 
                        width: '100%', 
                        maxWidth: '480px', 
                        borderRadius: '16px', 
                        boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)',
                        overflow: 'hidden'
                    }}>
                        {/* Modal Header */}
                        <div style={{ padding: '20px 24px', background: '#6366f1', color: '#fff' }}>
                            <h3 style={{ margin: 0, fontSize: '18px', fontWeight: 700 }}>Record Payment Collection</h3>
                            <span style={{ fontSize: '13px', opacity: 0.85, marginTop: '2px', display: 'block' }}>
                                Project: {collectingProject.name} ({collectingProject.projectNumber})
                            </span>
                        </div>

                        <form onSubmit={handleSubmitCollection} style={{ padding: '24px', display: 'flex', flexDirection: 'column', gap: '18px' }}>
                            {/* Target advance info card */}
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 16px', background: '#f5f3ff', borderRadius: '8px', border: '1px solid #ddd6fe' }}>
                                <span style={{ fontSize: '13px', color: '#5b21b6', fontWeight: 600 }}>Target Amount ({collectingProject?.paymentStatus !== 'Pending Advance' ? 'Balance' : 'Advance'}):</span>
                                <span style={{ fontSize: '16px', fontWeight: 800, color: '#5b21b6' }}>
                                    ₹{(collectingProject?.paymentStatus !== 'Pending Advance' ? (collectingProject.budget - (collectingProject.advanceAmount || collectingProject.collectedAmount || 0)) : (collectingProject.advanceAmount || 0)).toLocaleString('en-IN')}
                                </span>
                            </div>

                            {/* Input: Collected Amount */}
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                                <label style={{ fontSize: '13px', fontWeight: 600, color: '#334155' }}>Amount Collected (₹) *</label>
                                <input 
                                    type="number" 
                                    required
                                    placeholder="Enter amount"
                                    value={formData.collectedAmount} 
                                    onChange={e => setFormData(prev => ({ ...prev, collectedAmount: e.target.value }))}
                                    style={{ height: '40px', padding: '0 12px', border: '1px solid #cbd5e1', borderRadius: '8px', outline: 'none', fontSize: '14px' }} 
                                />
                            </div>

                            {/* Input: Mode of Payment */}
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                                <label style={{ fontSize: '13px', fontWeight: 600, color: '#334155' }}>Payment Mode *</label>
                                <select 
                                    value={formData.paymentMode}
                                    onChange={e => setFormData(prev => ({ ...prev, paymentMode: e.target.value }))}
                                    style={{ height: '40px', padding: '0 12px', border: '1px solid #cbd5e1', borderRadius: '8px', outline: 'none', fontSize: '14px', background: '#fff' }}
                                >
                                    <option value="Bank Transfer">Bank Transfer / NEFT</option>
                                    <option value="UPI">UPI (GPay / PhonePe / Paytm)</option>
                                    <option value="Cash">Cash</option>
                                    <option value="Cheque">Cheque</option>
                                </select>
                            </div>

                            {/* Input: Reference / Txn Number */}
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                                <label style={{ fontSize: '13px', fontWeight: 600, color: '#334155' }}>Reference / Txn ID</label>
                                <input 
                                    type="text" 
                                    placeholder="e.g. UTR number, Cheque no, or Receipt ID"
                                    value={formData.referenceNumber} 
                                    onChange={e => setFormData(prev => ({ ...prev, referenceNumber: e.target.value }))}
                                    style={{ height: '40px', padding: '0 12px', border: '1px solid #cbd5e1', borderRadius: '8px', outline: 'none', fontSize: '14px' }} 
                                />
                            </div>

                            {/* Input: Notes */}
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                                <label style={{ fontSize: '13px', fontWeight: 600, color: '#334155' }}>Remarks / Collection Notes</label>
                                <textarea 
                                    placeholder="Add any extra notes or payment remarks..."
                                    value={formData.paymentNotes} 
                                    onChange={e => setFormData(prev => ({ ...prev, paymentNotes: e.target.value }))}
                                    style={{ padding: '10px 12px', border: '1px solid #cbd5e1', borderRadius: '8px', outline: 'none', fontSize: '14px', minHeight: '80px', resize: 'vertical' }} 
                                />
                            </div>

                            {/* Footer Buttons */}
                            <div style={{ display: 'flex', gap: '12px', marginTop: '8px', justifyContent: 'flex-end' }}>
                                <button 
                                    type="button" 
                                    onClick={() => setCollectingProject(null)}
                                    disabled={submitting}
                                    style={{ 
                                        padding: '10px 18px', border: '1px solid #cbd5e1', borderRadius: '8px', 
                                        background: '#fff', color: '#475569', fontWeight: 600, fontSize: '14px', cursor: 'pointer' 
                                    }}
                                >
                                    Cancel
                                </button>
                                <button 
                                    type="submit" 
                                    disabled={submitting}
                                    style={{ 
                                        padding: '10px 22px', border: 'none', borderRadius: '8px', 
                                        background: '#6366f1', color: '#fff', fontWeight: 600, fontSize: '14px', cursor: 'pointer',
                                        display: 'flex', alignItems: 'center', gap: '8px'
                                    }}
                                >
                                    {submitting ? 'Saving...' : 'Record Payment'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default MyCollections;

import React, { useEffect, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { X, Zap, Loader2 } from 'lucide-react';
import { useAIChatState } from './ai-chat/hooks/useAIChatState';
import { useAIChatActions } from './ai-chat/hooks/useAIChatActions';

import ChatMessage from './ai-chat/components/ChatMessage';
import ChatInputArea from './ai-chat/components/ChatInputArea';
import ChatFAB from './ai-chat/components/ChatFAB';

import './css/AIChat.css';

const AIChat = () => {
    const location = useLocation();
    const navigate = useNavigate();
    const state = useAIChatState();
    const messagesEndRef = useRef(null);

    const actions = useAIChatActions({
        input: state.input,
        setInput: state.setInput,
        messages: state.messages,
        setMessages: state.setMessages,
        setIsLoading: state.setIsLoading,
        isLoading: state.isLoading,
        location,
        navigate
    });

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        scrollToBottom();
    }, [state.messages]);

    useEffect(() => {
        const timer = setTimeout(() => state.setShowWelcome(false), 8000);
        return () => clearTimeout(timer);
    }, []);

    const toggleChat = () => {
        state.setIsOpen(!state.isOpen);
        state.setShowWelcome(false);
    };

    return (
        <div className="ai-chat-container">
            {state.isOpen && (
                <div className="ai-window">
                    <div className="ai-header">
                        <div className="ai-header-info">
                            <div className="ai-bot-icon"><Zap size={20} /></div>
                            <div className="ai-title-group">
                                <h3>Antigravity Intel</h3>
                                <p>Powered by Gemini 1.5</p>
                            </div>
                        </div>
                        <button className="btn-close-chat" onClick={() => state.setIsOpen(false)}>
                            <X size={20} />
                        </button>
                    </div>

                    <div className="ai-messages">
                        {state.messages.map((msg, idx) => (
                            <ChatMessage 
                                key={idx} 
                                msg={msg} 
                                onFormConfirm={(updatedData) => actions.handleAIAction({
                                    action: 'SUBMIT_FORM',
                                    formType: msg.actionData.formType,
                                    data: updatedData
                                })}
                            />
                        ))}
                        {state.isLoading && (
                            <div className="message-wrapper bot">
                                <div className="msg-bot-avatar"><Loader2 className="spinner" size={16} /></div>
                                <div className="ai-message-bubble bot loading">Thinking...</div>
                            </div>
                        )}
                        <div ref={messagesEndRef} />
                    </div>

                    <ChatInputArea 
                        input={state.input}
                        setInput={state.setInput}
                        handleSend={actions.handleSend}
                        isLoading={state.isLoading}
                    />
                </div>
            )}

            <ChatFAB 
                isOpen={state.isOpen}
                toggleChat={toggleChat}
                showWelcome={state.showWelcome}
            />
        </div>
    );
};

export default AIChat;

import React from 'react';
import { TrendingUp, DollarSign, FileText, Package, ShoppingCart, Users } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

// Hooks
import { useDashboardState } from './dashboard/hooks/useDashboardState';
import { useDashboardData } from './dashboard/hooks/useDashboardData';

// Components
import KPICard from './dashboard/components/KPICard';
import RevenueCard from './dashboard/components/RevenueCard';
import ApprovalAlert from './dashboard/components/ApprovalAlert';
import { GraphicalAnalysis, TrendCharts } from './dashboard/components/DashboardCharts';
import Skeleton from './components/Skeleton';

import './css/Dashboard.css';
import { useAppSelector } from '../../store/hooks';
import { selectUser } from '../../store/slices/authSlice';

const Dashboard = ({}) => {
    const user = useAppSelector(selectUser);
    const navigate = useNavigate();
    const state = useDashboardState();

    useDashboardData({
        setStats: state.setStats, setPoStats: state.setPoStats,
        setRevenueData: state.setRevenueData, setQuotationData: state.setQuotationData,
        setLoading: state.setLoading, setError: state.setError
    });

    const getGreeting = () => {
        const hour = new Date().getHours();
        if (hour < 12) return "Good morning";
        if (hour < 18) return "Good afternoon";
        return "Good evening";
    };

    const sparkData = [
        { value: 40 }, { value: 35 }, { value: 55 }, { value: 45 }, { value: 60 }, { value: 50 }, { value: 75 }
    ];

    const formatCurrency = (amount) => {
        if (!amount) return '₹0';
        if (amount >= 100000) return `₹${(amount / 100000).toFixed(1)}L`;
        if (amount >= 1000) return `₹${(amount / 1000).toFixed(1)}K`;
        return `₹${amount.toLocaleString()}`;
    };

    // Prepare Pie Data
    const financialPieData = state.stats ? [
        { name: 'Generated (Approved)', value: state.stats.revenue.approved || 0, color: '#10b981' },
        { name: 'Pending (Potential)', value: state.stats.revenue.potential || 0, color: '#3b82f6' }
    ] : [];

    const quotationPieData = state.stats ? [
        { name: 'Approved', value: state.stats.quotations.approved || 0, color: '#10b981' },
        { name: 'Under Review', value: state.stats.quotations.pending || 0, color: '#f59e0b' }
    ] : [];

    const inventoryPieData = state.stats ? [
        { name: 'In Stock', value: state.stats.inventory.inStock || 0, color: '#10b981' },
        { name: 'Low Stock', value: state.stats.inventory.lowStock || 0, color: '#f59e0b' },
        { name: 'Out of Stock', value: state.stats.inventory.outOfStock || 0, color: '#ef4444' }
    ] : [];

    return (
        <div className="dashboard-wrapper">
            <div className="dashboard-content">
                <div className="dashboard-greeting">
                    {state.loading ? (
                        <>
                            <Skeleton width="280px" height="32px" />
                            <div style={{ marginTop: '8px' }}><Skeleton width="340px" height="16px" /></div>
                        </>
                    ) : (
                        <>
                            <h1>{getGreeting()}, {user?.fullName?.split(' ')[0] || 'Admin'} 👋</h1>
                            <p>Here's your comprehensive business overview.</p>
                        </>
                    )}
                </div>

                {state.error && <div className="error-banner"><span>Failed to load data: {state.error}</span></div>}

                <ApprovalAlert 
                    count={state.stats?.tasks?.pendingAdmin} 
                    loading={state.loading} 
                    onClick={() => navigate('/approvals')} 
                />

                <div className="stats-grid">
                    <KPICard title="Total Quotations" value={state.stats?.quotations?.total || 0} icon={FileText} color="#3b82f6" bgColor="#eff6ff" loading={state.loading} trend={{ type: 'positive', value: '12%' }} sparkData={sparkData} details={[{ label: 'Under Review', value: state.stats?.quotations?.pending || 0, color: '#f59e0b' }, { label: 'Approved', value: state.stats?.quotations?.approved || 0, color: '#10b981' }]} />
                    <KPICard title="Inventory Items" value={state.stats?.inventory?.totalCount || 0} icon={Package} color="#8b5cf6" bgColor="#f5f3ff" loading={state.loading} trend={{ type: 'neutral', value: '0%' }} sparkData={sparkData} details={[{ label: 'Low Stock', value: state.stats?.inventory?.lowStock || 0, color: '#f59e0b' }, { label: 'Out of Stock', value: state.stats?.inventory?.outOfStock || 0, color: '#ef4444' }]} />
                    <KPICard title="Purchase Orders" value={state.poStats.total} icon={ShoppingCart} color="#ec4899" bgColor="#fdf2f8" loading={state.loading} trend={{ type: 'negative', value: '3%' }} sparkData={sparkData} details={[{ label: 'Pending', value: state.poStats.pending, color: '#f59e0b' }, { label: 'Received', value: state.poStats.received, color: '#10b981' }]} />
                    <KPICard title="Active Clients" value={state.stats?.clients?.total || 0} icon={Users} color="#0ea5e9" bgColor="#f0f9ff" loading={state.loading} trend={{ type: 'positive', value: '8%' }} sparkData={sparkData} details={[{ label: 'Active', value: state.stats?.clients?.active || 0, color: '#10b981' }, { label: 'New', value: state.stats?.clients?.new || 0, color: '#0ea5e9' }]} />
                </div>

                <div className="graphical-analysis-grid">
                    {[1, 2, 3].map(i => (
                        <GraphicalAnalysis key={i} i={i} stats={state.stats} financialPieData={financialPieData} quotationPieData={quotationPieData} inventoryPieData={inventoryPieData} formatCurrency={formatCurrency} loading={state.loading} />
                    ))}
                </div>

                <TrendCharts revenueData={state.revenueData} quotationData={state.quotationData} loading={state.loading} />

                <div className="revenue-full-row">
                    <RevenueCard label="Total Earned (Approved)" value={formatCurrency(state.stats?.revenue?.approved || 0)} variant="green" icon={TrendingUp} loading={state.loading} />
                    <RevenueCard label="Potential Revenue" value={formatCurrency(state.stats?.revenue?.potential || 0)} variant="blue" icon={DollarSign} loading={state.loading} />
                </div>
            </div>
        </div>
    );
};

export default Dashboard;

import React, { useRef, useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { Bell, User, Settings, LogOut } from 'lucide-react';
import { useHeaderState } from './header/hooks/useHeaderState';
import { useNotificationLogic } from './header/hooks/useNotificationLogic';
import { useSearchLogic } from './header/hooks/useSearchLogic';

import WelcomeSection from './header/components/WelcomeSection';
import HeaderSearch from './header/components/HeaderSearch';
import HeaderActions from './header/components/HeaderActions';
import NotificationPopup from './header/components/NotificationPopup';

import './css/Header.css';
import { useAppSelector } from '../../store/hooks';
import { selectUser } from '../../store/slices/authSlice';

const getInitials = (name) => {
    const user = useAppSelector(selectUser);
    if (!name) return 'A';
    return name.split(' ').map(n => n[0]).join('').toUpperCase().substring(0, 2);
};

const Header = ({ toggleMobileSidebar, onLogout }) => {
    const location = useLocation();
    const user = useAppSelector(selectUser);
    const state = useHeaderState();
    const popupRef = useRef(null);
    const wrapperRef = useRef(null);
    const searchInputRef = useRef(null);
    const profileRef = useRef(null);
    const [isProfileOpen, setIsProfileOpen] = useState(false);

    const notificationLogic = useNotificationLogic({
        setNotifications: state.setNotifications,
        setUnreadCount: state.setUnreadCount,
        showNotifications: state.showNotifications,
        setShowNotifications: state.setShowNotifications,
        notifications: state.notifications
    });

    const searchLogic = useSearchLogic({
        setSearchValue: state.setSearchValue,
        setSearchOpen: state.setSearchOpen,
        pathname: location.pathname,
        searchInputRef
    });

    useEffect(() => {
        const handleClickOutside = (e) => {
            if (wrapperRef.current && !wrapperRef.current.contains(e.target)) {
                state.setShowNotifications(false);
            }
            if (profileRef.current && !profileRef.current.contains(e.target)) {
                setIsProfileOpen(false);
            }
        };
        if (state.showNotifications || isProfileOpen) {
            document.addEventListener('mousedown', handleClickOutside);
            document.addEventListener('touchstart', handleClickOutside);
        }
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
            document.removeEventListener('touchstart', handleClickOutside);
        };
    }, [state.showNotifications, isProfileOpen]);

    const getPageDetails = () => {
        const path = location.pathname;
        const tab = new URLSearchParams(location.search).get('tab')?.toLowerCase();

        const getGreeting = () => {
            const hour = new Date().getHours();
            if (hour < 12) return "Good Morning";
            if (hour < 18) return "Good Afternoon";
            return "Good Evening";
        };
        const userName = user?.fullName?.split(' ')[0] || 'Admin';

        if (path === '/') {
            if (tab === 'invoices') return { title: 'Invoices', subtitle: 'Manage your client invoices.' };
            if (tab === 'expenses') return { title: 'Expenses', subtitle: 'Track your business spending.' };
            if (tab === 'payments') return { title: 'Payments', subtitle: 'Manage your incoming payments.' };
            if (tab === 'clients') return { title: 'Clients', subtitle: 'Manage your client database.' };
            if (tab === 'vendors') return { title: 'Vendors', subtitle: 'Manage your vendors and suppliers.' };
            if (tab === 'projects') return { title: 'Projects', subtitle: 'Manage your ongoing projects.' };
            if (tab === 'reports') return { title: 'Analytics Reports', subtitle: 'Detailed overview of performance.' };
            if (tab === 'pipeline') return { title: 'Design Pipeline', subtitle: 'Manage your studio workflow.' };
            if (tab === 'overview' || tab === 'dashboard') {
                return { 
                    title: `${getGreeting()}, ${userName} 👋`, 
                    subtitle: "Here's your financial overview today." 
                };
            }
            if (tab === 'requests') return { title: 'Material Requests', subtitle: 'Manage pending material requests.' };
            return { title: 'Dashboard', subtitle: "Welcome back! Here's your business overview." };
        }

        const staticMap = {
            '/quotations': { title: 'Quotations', subtitle: 'Detailed overview of project estimates.' },
            '/quotations/new': { title: 'New Quotation', subtitle: 'Craft a professional estimate.' },
            '/inventory': { title: 'Global Inventory', subtitle: 'Track your primary design materials.' },
            '/purchase-orders': { title: 'Purchase Orders', subtitle: 'Manage supplier orders.' },
            '/po-inventory': { title: 'PO Tracking', subtitle: 'Monitor stock received through POs.' },
            '/clients': { title: 'Relationships', subtitle: 'Manage your client database.' },
            '/tasks': { title: 'Tasks Hub', subtitle: 'Keep track of project milestones.' },
            '/reports': { title: 'Analytics', subtitle: 'Deep dive into your revenue metrics.' },
            '/settings': { title: 'System Controls', subtitle: 'Configure your preferences.' },
            '/users': { title: 'Team Access', subtitle: 'Manage staff accounts.' },
            '/invoice': { title: 'Invoices', subtitle: 'Generate and track professional client invoices.' },
            '/projects': { title: 'Projects', subtitle: 'Detailed overview of all ongoing projects.' },
            '/staff': { title: 'Staff', subtitle: 'Manage your team members and roles.' },
            '/approvals': { title: 'Approvals', subtitle: 'Review and manage pending design approvals.' },
            '/material-review': { title: 'Material Review', subtitle: 'Review and approve material requests.' },
            '/engineer/dashboard': { title: 'Dashboard', subtitle: 'Overview of assigned tasks' },
            '/engineer/projects': { title: 'My Projects', subtitle: 'Projects you are assigned to' },
            '/engineer/tasks': { title: 'My Tasks', subtitle: 'All tasks assigned to you' },
            '/engineer/leave': { title: 'Leave Request', subtitle: 'Submit and track applications' },
            '/engineer/reports': { title: 'Site Monitoring', subtitle: 'Review daily progress logs' },
            '/engineer/approvals': { title: 'Approvals', subtitle: 'Review and approve requests' },
            '/site/dashboard': { title: 'Dashboard', subtitle: 'Your site tasks at a glance' },
            '/site/projects': { title: 'My Projects', subtitle: 'Projects assigned to you' },
            '/site/tasks': { title: 'My Tasks', subtitle: 'Tasks assigned from Engineer' },
            '/site/transferred-tasks': { title: 'Transferred Tasks', subtitle: 'Tasks delegated to supervisors' },
            '/site/reports': { title: 'Site Reports', subtitle: 'Submit daily progress reports' },
            '/site/leave': { title: 'Leave Request', subtitle: 'Submit and track applications' },
            '/meetings': { title: 'Meetings', subtitle: 'Schedule and manage Google Meet sessions.' },
        };

        if (staticMap[path]) return staticMap[path];

        if (path.startsWith('/production-management/dashboard')) return { title: 'Production Dashboard', subtitle: 'Overview of operations' };
        if (path.startsWith('/production-management/projects')) return { title: 'Projects Overview', subtitle: 'Manage projects' };
        if (path.startsWith('/production-management/tasks')) return { title: 'Tasks Board', subtitle: 'Track production tasks' };
        if (path.startsWith('/production-management/team')) return { title: 'Team Directory', subtitle: 'Manage team members' };
        if (path.startsWith('/production-management/approvals')) return { title: 'Approvals & Requests', subtitle: 'Review requests' };
        if (path.startsWith('/production-management/handoff')) return { title: 'Project Handoff', subtitle: 'Review new projects' };
        if (path.startsWith('/production-management/reports')) return { title: 'Reports & Export', subtitle: 'Analytics data' };
        if (path.startsWith('/engineer/projects/')) return { title: 'Project Detail', subtitle: 'Project overview and tasks' };
        if (path.startsWith('/site/projects/')) return { title: 'Project Detail', subtitle: 'Project overview and tasks' };
        if (path.startsWith('/engineer/tasks/')) return { title: 'Task Detail', subtitle: 'Full task view' };
        if (path.startsWith('/site/tasks/')) return { title: 'Task Detail', subtitle: 'Full task view' };

        return {
            title: path.replace('/', '').split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' '),
            subtitle: ''
        };
    };

    const { title, subtitle } = getPageDetails();
    const tab = new URLSearchParams(location.search).get('tab')?.toLowerCase();
    const isDashboard = location.pathname === '/' && (!tab || tab === 'overview' || tab === 'dashboard');

    const searchablePaths = ['/', '/users', '/tasks', '/clients', '/inventory', '/invoice', '/quotations', '/staff', '/purchase-orders', '/po-inventory', '/projects', '/production-management/team', '/engineer/projects', '/site/projects'];
    const isSearchable = searchablePaths.includes(location.pathname) && !isDashboard;

    return (
        <header className="page-header">
            <WelcomeSection 
                title={title}
                subtitle={subtitle}
                toggleMobileSidebar={toggleMobileSidebar}
            />

            <div className="page-header-actions">
                <HeaderSearch 
                    isSearchable={isSearchable}
                    searchOpen={state.searchOpen}
                    searchValue={state.searchValue}
                    handleSearchToggle={searchLogic.handleSearchToggle}
                    handleSearchChange={searchLogic.handleSearchChange}
                    searchInputRef={searchInputRef}
                />

                {location.pathname === '/' && new URLSearchParams(location.search).get('tab') === 'overview' && (
                    <div className="header-date-filter" style={{ display: 'flex', alignItems: 'center', background: '#f8fafc', padding: '6px 12px', borderRadius: '8px', border: '1px solid #e2e8f0', color: '#475569', fontSize: '13px', fontWeight: '500', cursor: 'pointer', gap: '6px' }}>
                        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect><line x1="16" y1="2" x2="16" y2="6"></line><line x1="8" y1="2" x2="8" y2="6"></line><line x1="3" y1="10" x2="21" y2="10"></line></svg>
                        <span>This Month</span>
                        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ marginLeft: '4px' }}><polyline points="6 9 12 15 18 9"></polyline></svg>
                    </div>
                )}

                <HeaderActions 
                    isHome={location.pathname === '/'}
                    tab={new URLSearchParams(location.search).get('tab')}
                    location={location}
                    user={user}
                />

                <div className="header-notification-wrapper" ref={wrapperRef}>
                    <button
                        className={`header-notification-btn ${state.showNotifications ? 'active' : ''}`}
                        onClick={notificationLogic.toggleNotifications}
                    >
                        <Bell size={19} strokeWidth={2.2} />
                        {state.unreadCount > 0 && (
                            <span className="header-notification-badge">
                                {state.unreadCount > 9 ? '9+' : state.unreadCount}
                            </span>
                        )}
                    </button>

                    <NotificationPopup 
                        showNotifications={state.showNotifications}
                        notifications={state.notifications}
                        unreadCount={state.unreadCount}
                        handleMarkAsRead={notificationLogic.handleMarkAsRead}
                        handleMarkAllRead={notificationLogic.handleMarkAllRead}
                        handleDelete={notificationLogic.handleDelete}
                        setShowNotifications={state.setShowNotifications}
                        popupRef={popupRef}
                    />
                </div>

                <div className="mobile-profile-wrapper" ref={profileRef} style={{ position: 'relative' }}>
                    <button 
                        className="header-profile-btn"
                        onClick={() => {
