import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Save, Send, X } from 'lucide-react';

// Hooks
import { useQuotationState } from './quotation/hooks/useQuotationState';
import { useQuotationData } from './quotation/hooks/useQuotationData';
import { useQuotationSearch } from './quotation/hooks/useQuotationSearch';
import { useQuotationCalculations } from './quotation/hooks/useQuotationCalculations';
import { useQuotationActions } from './quotation/hooks/useQuotationActions';

// Components
import ProjectDetailsSection from './quotation/components/ProjectDetailsSection';
import PaymentPoliciesSection from './quotation/components/PaymentPoliciesSection';
import LineItemsSection from './quotation/components/LineItemsSection';
import QuotationSummary from './quotation/components/QuotationSummary';
import NewQuotationSkeleton from './quotation/components/NewQuotationSkeleton';
import { BillPreviewModal, QuickAddClientModal, ExitConfirmationDialog } from './quotation/components/QuotationModals';

import './css/NewQuotation.css';

const NewQuotation = ({ isEdit, isStaff }) => {
    const navigate = useNavigate();
    const { id } = useParams();

    // Global UI states
    const [fetching, setFetching] = useState(isEdit && !!id);
    const [error, setError] = useState(null);
    const [fieldErrors, setFieldErrors] = useState({});
    const [isSaving, setIsSaving] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [showBillPreview, setShowBillPreview] = useState(false);
    const [showQuickAddModal, setShowQuickAddModal] = useState(false);
    const [showExitDialog, setShowExitDialog] = useState(false);
    const [pendingStatus, setPendingStatus] = useState('Under Review');
    const [quickAddData, setQuickAddData] = useState({ name: '', email: '', phone: '' });

    // Data states
    const [clients, setClients] = useState([]);
    const [inventoryItems, setInventoryItems] = useState([]);

    // Logic Hooks
    const state = useQuotationState();

    useQuotationData({
        isEdit, id, setFormData: state.setFormData, setLineItems: state.setLineItems,
        setTaxRate: state.setTaxRate, setDiscount: state.setDiscount,
        setIncludeDiscount: state.setIncludeDiscount, setFetching, setError,
        setClients, setInventoryItems, clients
    });

    const search = useQuotationSearch({
        clients, inventoryItems, setFormData: state.setFormData,
        setLineItems: state.setLineItems, lineItems: state.lineItems
    });

    const calc = useQuotationCalculations({
        lineItems: state.lineItems, includeDiscount: state.includeDiscount,
        discount: state.discount, includeTax: state.includeTax,
        taxRate: state.taxRate, formData: state.formData
    });

    const actions = useQuotationActions({
        formData: state.formData, lineItems: state.lineItems, taxRate: state.taxRate,
        discount: state.discount, includeDiscount: state.includeDiscount,
        offerPrice: calc.offerPrice, isEdit, id, isStaff, navigate, setError,
        setIsSaving, setShowBillPreview, setPendingStatus, setClients,
        setShowQuickAddModal, setShowExitDialog, setFieldErrors
    });

    // Clear field-level error when user enters value
    useEffect(() => {
        if (state.formData.client) {
            setFieldErrors(prev => {
                const next = { ...prev };
                delete next.client;
                return next;
            });
        }
    }, [state.formData.client]);

    useEffect(() => {
        if (state.formData.projectName) {
            setFieldErrors(prev => {
                const next = { ...prev };
                delete next.projectName;
                return next;
            });
        }
    }, [state.formData.projectName]);

    useEffect(() => {
        if (state.lineItems.length > 0) {
            setFieldErrors(prev => {
                const next = { ...prev };
                delete next.lineItems;
                return next;
            });
        }
    }, [state.lineItems.length]);

    // Handle clicks outside for search suggestions
    useEffect(() => {
        const handleClickOutside = () => search.setShowClientSuggestions(false);
        document.addEventListener('click', handleClickOutside);
        return () => document.removeEventListener('click', handleClickOutside);
    }, [search]);

    if (fetching) return <NewQuotationSkeleton />;

    return (
        <div className="new-quote-wrapper" style={{ position: 'relative', overflow: showBillPreview ? 'hidden' : 'auto' }}>
            <div className="form-container" style={{
                filter: showBillPreview ? 'blur(10px) brightness(0.9)' : 'none',
                pointerEvents: showBillPreview ? 'none' : 'auto',
                transition: 'all 0.4s'
            }}>
                {error && <div className="error-banner">{error}</div>}

                <form onSubmit={(e) => actions.handlePreview(e)} noValidate>
                    <ProjectDetailsSection
                        formData={state.formData}
                        handleInputChange={state.handleInputChange}
                        clientSearchQuery={search.clientSearchQuery}
                        handleClientSearch={search.handleClientSearch}
                        showClientSuggestions={search.showClientSuggestions}
                        filteredClients={search.filteredClients}
                        selectClient={search.selectClient}
                        handleQuickAddClient={() => setShowQuickAddModal(true)}
                        setFormData={state.setFormData}
                        fieldErrors={fieldErrors}
                    />

                    <PaymentPoliciesSection
                        formData={state.formData}
                        handleInputChange={state.handleInputChange}
                        depositAmount={calc.depositAmount}
                    />

                    <LineItemsSection
                        lineItems={state.lineItems}
                        addLineItem={state.addLineItem}
                        removeLineItem={state.removeLineItem}
                        updateLineItem={state.updateLineItem}
                        expandedItems={state.expandedItems}
                        setExpandedItems={state.setExpandedItems}
                        globalSearchQuery={search.globalSearchQuery}
                        setGlobalSearchQuery={search.setGlobalSearchQuery}
                        globalSearchResults={search.globalSearchResults}
                        handleGlobalSearch={search.handleGlobalSearch}
                        addFromInventorySelect={search.addFromInventorySelect}
                        activeSearchId={search.activeSearchId}
                        searchResults={search.searchResults}
                        handleProductSearch={search.handleProductSearch}
                        selectProduct={search.selectProduct}
                        handleImageUpload={(itemId, file) => actions.handleImageUpload(itemId, file, state.updateLineItem)}
                        fieldErrors={fieldErrors}
                    />

                    <QuotationSummary
                        {...calc}
                        includeDiscount={state.includeDiscount}
                        setIncludeDiscount={state.setIncludeDiscount}
                        discount={state.discount}
                        setDiscount={state.setDiscount}
                        includeTax={state.includeTax}
                        setIncludeTax={state.setIncludeTax}
                        taxRate={state.taxRate}
                        setTaxRate={state.setTaxRate}
                    />

                    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginTop: '2rem' }}>
                        <div className="form-section">
                            <label className="section-label">Notes</label>
                            <textarea name="notes" className="textarea-styled" value={state.formData.notes} onChange={state.handleInputChange} rows="2"></textarea>
                        </div>
                        <div className="form-section">
                            <label className="section-label">Terms & Conditions</label>
                            <textarea name="termsConditions" className="textarea-styled" value={state.formData.termsConditions} onChange={state.handleInputChange} rows="2"></textarea>
                        </div>
                    </div>

                    <div className="form-footer-actions">
                        <button type="button" className="btn-exit" onClick={() => setShowExitDialog(true)}>
                            <X size={18} /> Exit
                        </button>
                        <button type="button" className="btn-save-draft" onClick={(e) => actions.handlePreview(e, 'Draft')}>
                            <Save size={18} /> Review Draft
                        </button>
                        <button type="submit" className="btn-send-quote">
                            <Send size={18} /> Review & Save
                        </button>
                    </div>
                </form>
            </div>

            <BillPreviewModal
                show={showBillPreview} setShow={setShowBillPreview}
                formData={state.formData} clients={clients} lineItems={state.lineItems}
                {...calc} includeDiscount={state.includeDiscount} discount={state.discount}
                includeTax={state.includeTax} taxRate={state.taxRate}
                handleFinalSave={() => actions.handleFinalSave(pendingStatus)}
                isSaving={isSaving}
            />

            <QuickAddClientModal
                show={showQuickAddModal} setShow={setShowQuickAddModal}
                quickAddData={quickAddData} setQuickAddData={setQuickAddData}
                confirmQuickAddClient={(e) => actions.confirmQuickAddClient(e, quickAddData, search.selectClient)}
                isSubmitting={isSubmitting}
            />

            <ExitConfirmationDialog
                show={showExitDialog} setShow={setShowExitDialog}
                handleSaveDraft={actions.handleSaveDraft} isSaving={isSaving}
                onDiscard={() => navigate(isStaff ? '/staff/quotations' : '/quotations')}
            />
        </div>
    );
};

export default NewQuotation;

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useProjectState } from './projects/hooks/useProjectState';
import { useProjectData } from './projects/hooks/useProjectData';
import { useProjectActions } from './projects/hooks/useProjectActions';

import ProjectFilterBar from './projects/components/ProjectFilterBar';
import ProjectWorkflow from './projects/components/ProjectWorkflow';
import ProjectKPIs from './projects/components/ProjectKPIs';
import ProjectTabs from './projects/components/ProjectTabs';
import ProjectTable from './projects/components/ProjectTable';
import ProjectTimeline from './projects/components/ProjectTimeline';
import ProjectDetailModal from './projects/components/ProjectDetailModal';
import ProjectEditModal from './projects/components/ProjectEditModal';
import ProjectFocusedView from './projects/components/ProjectFocusedView';
import AlertDialog from './components/AlertDialog';
import { TableSkeleton, StatsSkeleton } from './components/Skeleton';

import './css/Projects.css';

const Projects = () => {
    const navigate = useNavigate();
    const { id: urlProjectId } = useParams();
    const state = useProjectState();
    const [projectToDelete, setProjectToDelete] = useState(null);
    const [projectToEdit, setProjectToEdit] = useState(null);
    const [isDeleting, setIsDeleting] = useState(false);

    const { fetchProjects } = useProjectData({
        setProjects: state.setProjects,
        setLoading: state.setLoading,
        setSelectedProject: state.setSelectedProject,
        stageFilter: state.stageFilter,
        statusFilter: state.statusFilter,
        urlProjectId,
        setSearchTerm: state.setSearchTerm
    });

    const actions = useProjectActions({
        fetchProjects,
        setSelectedProject: state.setSelectedProject,
        navigate,
        urlProjectId
    });

    const handleConfirmDeleteList = async () => {
        if (!projectToDelete) return;
        setIsDeleting(true);
        try {
            await actions.handleDeleteProject(projectToDelete._id);
            setProjectToDelete(null);
        } catch (error) {
            console.error("Failed to delete project:", error);
            alert("Failed to delete project. Please try again.");
        } finally {
            setIsDeleting(false);
        }
    };

    useEffect(() => {
        const handleOpenModal = () => state.setShowModal(true);
        window.addEventListener('open-create-project-modal', handleOpenModal);
        return () => window.removeEventListener('open-create-project-modal', handleOpenModal);
    }, []);

    const filteredProjects = state.projects.filter(p => 
        p.name?.toLowerCase().includes(state.searchTerm.toLowerCase()) ||
        p.projectNumber?.toLowerCase().includes(state.searchTerm.toLowerCase())
    );

    if (urlProjectId || state.selectedProject) {
        const projectToView = urlProjectId ? state.selectedProject : state.selectedProject;
        return (
            <ProjectFocusedView 
                project={projectToView} 
                loading={state.loading} 
                handleClose={actions.handleClose}
                handleDeleteProject={actions.handleDeleteProject}
            />
        );
    }

    if (state.loading) {
        return (
            <div className="projects-page" style={{ padding: '2rem 2.5rem', minHeight: '100vh', margin: '-24px -24px 0 -24px', maxWidth: 'none' }}>
                <StatsSkeleton count={6} />
                <div style={{ marginTop: '2rem' }}>
                    <TableSkeleton rows={8} cols={5} />
                </div>
            </div>
        );
    }

    const renderActiveView = () => {
        switch (state.activeView) {
            case 'table':
                return <ProjectTable projects={filteredProjects} onProjectClick={state.setSelectedProject} onEditClick={setProjectToEdit} onDeleteClick={setProjectToDelete} />;
            case 'timeline':
                return <ProjectTimeline projects={filteredProjects} />;
            case 'archive': {
                const archivedProjects = filteredProjects.filter(p => p.stage === 'Completed');
                return <ProjectTable projects={archivedProjects} onProjectClick={state.setSelectedProject} onEditClick={setProjectToEdit} onDeleteClick={setProjectToDelete} />;
            }
            case 'kanban':
            default: {
                const activeProjects = filteredProjects.filter(p => p.stage !== 'Completed');
                return (
                    <ProjectWorkflow 
                        projects={activeProjects}
                        loading={state.loading}
                        stageFilter={state.stageFilter}
                        setSelectedProject={state.setSelectedProject}
                        groupBy={state.groupBy}
                    />
                );
            }
        }
    };

    return (
        <div className="projects-page">

            <ProjectKPIs projects={state.projects} />

            <div className="projects-controls">
                <ProjectTabs activeView={state.activeView} setActiveView={state.setActiveView} />

                <ProjectFilterBar 
                    searchTerm={state.searchTerm}
                    setSearchTerm={state.setSearchTerm}
                    stageFilter={state.stageFilter}
                    setStageFilter={state.setStageFilter}
                    statusFilter={state.statusFilter}
                    setStatusFilter={state.setStatusFilter}
                    showStageDropdown={state.showStageDropdown}
                    setShowStageDropdown={state.setShowStageDropdown}
                    showStatusDropdown={state.showStatusDropdown}
                    setShowStatusDropdown={state.setShowStatusDropdown}
                    showGroupByDropdown={state.showGroupByDropdown}
                    setShowGroupByDropdown={state.setShowGroupByDropdown}
                    hideSearch={true}
                    groupBy={state.groupBy}
                    setGroupBy={state.setGroupBy}
                />
            </div>

            <div className="view-content">
                {renderActiveView()}
            </div>

            {state.showModal && (
                <div className="modal-overlay" onClick={() => state.setShowModal(false)}>
                    <div className="modal-content" onClick={e => e.stopPropagation()}>
                        <div className="modal-header">
                            <h2>Create New Project</h2>
                            <button className="close-btn" onClick={() => state.setShowModal(false)}>×</button>
                        </div>
                        <div className="modal-body">
                            <p>Project creation from approved quotations is automatic.</p>
                            <p>Quotations can be approved from the Quotations section.</p>
                        </div>
                    </div>
                </div>
            )}

            <ProjectDetailModal 
                selectedProject={state.selectedProject}
                handleClose={actions.handleClose}
                onUpdate={fetchProjects}
            />

            <ProjectEditModal
                project={projectToEdit}
                onClose={() => setProjectToEdit(null)}
                onUpdate={fetchProjects}
            />

            <AlertDialog 
                isOpen={!!projectToDelete}
                onClose={() => setProjectToDelete(null)}
                onConfirm={handleConfirmDeleteList}
                title="Delete Project"
                description={`Are you sure you want to delete "${projectToDelete?.name}"? This action cannot be undone. This will permanently delete the project and all related tasks/data from the system.`}
                confirmText="Delete Project"
                isProcessing={isDeleting}
            />
        </div>
    );
};

export default Projects;

import React, { useEffect } from 'react';
import { Check, X } from 'lucide-react';
import { BASE_IMAGE_URL } from '../../config/constants';

// Hooks
import { useSettingsState } from './settings/hooks/useSettingsState';
import { useSettingsData } from './settings/hooks/useSettingsData';
import { useSettingsActions } from './settings/hooks/useSettingsActions';

// Components
import SettingsTabs from './settings/components/SettingsTabs';
import CompanyProfile from './settings/components/CompanyProfile';
import DocumentDefaults from './settings/components/DocumentDefaults';
import NotificationSettings from './settings/components/NotificationSettings';
import SecuritySettings from './settings/components/SecuritySettings';
import UserProfile from './settings/components/UserProfile';
import ApplicationSettings from './settings/components/ApplicationSettings';
import DataBackup from './settings/components/DataBackup';

import './css/Settings.css';

const Settings = () => {
    const state = useSettingsState();

    const data = useSettingsData({
        setSettings: state.setSettings, setProfile: state.setProfile,
        setLoading: state.setLoading, setSaving: state.setSaving,
        showToast: state.showToast, updateSettingsField: state.updateSettingsField
    });

    const actions = useSettingsActions({
        settings: state.settings, profile: state.profile, setProfile: state.setProfile,
        passwords: state.passwords, setPasswords: state.setPasswords,
        setSaving: state.setSaving, showToast: state.showToast
    });

    useEffect(() => {
        if (state.toast) {
            const timer = setTimeout(() => state.setToast(null), 3000);
            return () => clearTimeout(timer);
        }
    }, [state.toast]);

    const getImageUrl = (path) => {
        if (!path) return null;
        if (path.startsWith('http')) return path;
        return `${BASE_IMAGE_URL}${path.startsWith('/') ? '' : '/'}${path}`;
    };

    const renderTabContent = () => {
        const props = {
            settings: state.settings,
            updateSettingsField: state.updateSettingsField,
            saveSettings: actions.saveSettings,
            saving: state.saving,
            showToast: state.showToast
        };

        switch (state.activeTab) {
            case 'company': 
                return <CompanyProfile {...props} logoInputRef={state.logoInputRef} handleFileUpload={data.handleFileUpload} getImageUrl={getImageUrl} />;
            case 'documents': 
                return <DocumentDefaults {...props} />;
            case 'notifications': 
                return <NotificationSettings {...props} />;
            case 'security': 
                return <SecuritySettings {...props} />;
            case 'profile': 
                return (
                    <UserProfile 
                        {...props}
                        profile={state.profile} setProfile={state.setProfile}
                        avatarInputRef={state.avatarInputRef} handleFileUpload={data.handleFileUpload}
                        getImageUrl={getImageUrl} saveProfile={actions.saveProfile}
                        passwords={state.passwords} setPasswords={state.setPasswords}
                        showPasswords={state.showPasswords} setShowPasswords={state.setShowPasswords}
                        changePassword={actions.changePassword}
                    />
                );
            case 'application': 
                return <ApplicationSettings {...props} />;
            case 'data': 
                return <DataBackup showToast={state.showToast} />;
            default: 
                return null;
        }
    };

    if (state.loading) {
        return (
            <div className="settings-container">
                <div className="settings-wrapper">
                    <div className="settings-layout">
                        <div className="settings-tabs">
                            {[...Array(7)].map((_, i) => <div key={i} className="skeleton" style={{ height: '48px', marginBottom: '8px', borderRadius: '12px' }} />)}
                        </div>
                        <div className="settings-content"><div className="skeleton" style={{ height: '600px', borderRadius: '24px' }} /></div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="settings-container">
            <div className="settings-wrapper">
                <div className="settings-layout">
                    <SettingsTabs activeTab={state.activeTab} setActiveTab={state.setActiveTab} />
                    <div className="settings-content">
                        <div className="settings-section-card">
                            {renderTabContent()}
                        </div>
                    </div>
                </div>
            </div>

            {state.toast && (
                <div className={`settings-toast ${state.toast.type}`}>
                    {state.toast.type === 'success' ? <Check size={18} /> : <X size={18} />}
                    {state.toast.message}
                </div>
            )}
        </div>
    );
};

export default Settings;

import React from 'react';
import { useNavGroups } from './sidebar/hooks/useNavGroups';
