            <TaskFormModal 
                show={state.showTaskModal}
                closeModal={() => { state.setShowTaskModal(false); state.setEditingTask(null); state.setFormData(state.initialFormData); }}
                editingTask={state.editingTask}
                handleSubmit={actions.handleSubmit}
