import { 
    useCreateQuotationMutation, 
    useUpdateQuotationMutation,
    useCreateClientMutation 
} from '../../../../store/api/adminApi';
import { useUploadImageMutation } from '../../../../store/api/sharedApi';

export const useQuotationActions = ({
    formData,
    lineItems,
    taxRate,
    discount,
    includeDiscount,
    offerPrice,
    isEdit,
    id,
    isStaff,
    navigate,
    setError,
    setIsSaving,
    setShowBillPreview,
    setPendingStatus,
    setClients,
    setShowQuickAddModal,
    setShowExitDialog,
    setFieldErrors
}) => {

    const [createQuotation] = useCreateQuotationMutation();
    const [updateQuotation] = useUpdateQuotationMutation();
    const [createClient] = useCreateClientMutation();

    const handlePreview = (e, status = 'Under Review') => {
        if (e) e.preventDefault();

        const errors = {};
        if (!formData.client) {
            errors.client = 'Client is required.';
        }
        if (!formData.projectName) {
            errors.projectName = 'Project name is required.';
        }
        if (!lineItems || lineItems.length === 0) {
            errors.lineItems = 'Please add at least one line item.';
        }

        if (Object.keys(errors).length > 0) {
            setFieldErrors(errors);
            setError('Please correct the highlighted fields before proceeding.');

            setTimeout(() => {
                const firstErrorKey = Object.keys(errors)[0];
                const element = document.getElementById(`${firstErrorKey}-field-group`);
                if (element) {
                    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    const input = element.querySelector('input, textarea, select');
                    if (input) input.focus();
                } else {
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                }
            }, 100);
            return;
        }

        setFieldErrors({});
        setError(null);
        setPendingStatus(status);
        setShowBillPreview(true);
    };

    const handleFinalSave = async (pendingStatus) => {
        try {
            setIsSaving(true);
            const quotationData = {
                ...formData,
                quotationNumber: formData.quoteNumber,
                status: pendingStatus,
                taxRate,
                discount: includeDiscount ? discount : 0,
                offerPrice,
                items: lineItems.map(item => ({
                    itemName: item.name,
                    description: item.description,
                    section: item.section,
                    finish: item.finishBrand,
                    material: item.materialOrigin,
                    size: item.size,
                    unit: item.unit,
                    quantity: item.quantity,
                    rate: item.rate,
                    costPrice: item.costPrice || 0,
                    amount: item.amount,
                    image: item.image
                }))
            };

            if (isEdit) {
                await updateQuotation({ id, ...quotationData }).unwrap();
            } else {
                await createQuotation(quotationData).unwrap();
            }

            navigate(isStaff ? '/staff/quotations' : '/quotations');
        } catch (err) {
            setError(err.data?.message || err.message);
            setShowBillPreview(false);
        } finally {
            setIsSaving(false);
        }
    };

    const handleSaveDraft = async () => {
        try {
            setIsSaving(true);
            const quotationData = {
                ...formData,
                quotationNumber: formData.quoteNumber,
                status: 'Draft',
                taxRate,
                discount: includeDiscount ? discount : 0,
                items: lineItems.map(item => ({
                    itemName: item.name,
                    description: item.description,
                    section: item.section,
                    finish: item.finishBrand,
                    material: item.materialOrigin,
                    size: item.size,
                    unit: item.unit,
                    quantity: item.quantity,
                    rate: item.rate,
                    costPrice: item.costPrice || 0,
                    amount: item.amount,
                    image: item.image
                }))
            };

            if (isEdit) {
                await updateQuotation({ id, ...quotationData, status: 'Draft' }).unwrap();
            } else {
                await createQuotation(quotationData).unwrap();
            }

            setShowExitDialog(false);
            navigate(isStaff ? '/staff/quotations' : '/quotations');
        } catch (err) {
            setError('Failed to save draft: ' + (err.data?.message || err.message));
            setShowExitDialog(false);
        } finally {
            setIsSaving(false);
        }
    };

    const handleImageUpload = async (itemId, file, updateLineItem) => {
        if (!file) return;
        try {
            const fd = new FormData();
            fd.append('image', file);
            const result = await uploadImage(fd).unwrap();
            if (result.success) updateLineItem(itemId, 'image', result.data);
        } catch (err) {
            console.error('Upload error:', err);
        }
    };

    const confirmQuickAddClient = async (e, quickAddData, selectClient) => {
        e.preventDefault();
        try {
            const newClient = await createClient({ ...quickAddData, status: 'Active' }).unwrap();
            // Assuming the RTK query mutation might return data directly or nested in `data` depending on transformResponse, but .unwrap() usually gives the direct payload. Wait, previous models/api returned {success, data}. If the backend still returns {success, data}, then .unwrap() returns that object. Let's see:
            // if newClient has `.data`, we extract it.
            const clientData = newClient.data ? newClient.data : newClient;

            setClients(prev => [...prev, clientData]);
            selectClient(clientData);
            setShowQuickAddModal(false);
        } catch (err) {
            setError('Failed to create client: ' + (err.data?.message || err.message));
        }
    };

    return {
        handlePreview,
        handleFinalSave,
        handleSaveDraft,
        handleImageUpload,
        confirmQuickAddClient
    };
};

import { useState, useEffect } from 'react';
import { useGetClientsQuery, useGetInventoryQuery, useGetQuotationByIdQuery } from '../../../../store/api/adminApi';

export const useQuotationData = ({ isEdit, id, setFormData, setLineItems, setTaxRate, setDiscount, setIncludeDiscount, setFetching, setError, setClients, setInventoryItems, clients }) => {

    const { data: clientsRes, isLoading: clientsLoading, error: clientsError } = useGetClientsQuery();
    const { data: inventoryRes, isLoading: inventoryLoading, error: inventoryError } = useGetInventoryQuery({ limit: 1000 });
    const { data: quoteRes, isLoading: quoteLoading, error: quoteError } = useGetQuotationByIdQuery(id, { skip: !isEdit || !id });

    // Initial Data Fetch
    useEffect(() => {
        if (clientsLoading || inventoryLoading || (isEdit && id && quoteLoading)) {
            setFetching(true);
            return;
        }

        if (clientsError || inventoryError || quoteError) {
            setError('Failed to load data.');
            setFetching(false);
            return;
        }

        if (clientsRes?.success) setClients(clientsRes.data);
        if (inventoryRes?.success) setInventoryItems(inventoryRes.data);

        if (isEdit && id && quoteRes?.success) {
            const q = quoteRes.data;
            const clientData = q.client?._id || q.client;
            setFormData({
                client: clientData,
                clientPhone: q.clientPhone || '',
                quoteNumber: q.quotationNumber,
                date: new Date(q.createdAt).toISOString().split('T')[0],
                validUntil: q.validUntil ? new Date(q.validUntil).toISOString().split('T')[0] : '',
                documentType: q.documentType || 'Quotation',
                projectName: q.projectName,
                projectDescription: q.projectDescription || '',
                projectStart: q.projectStart ? new Date(q.projectStart).toISOString().split('T')[0] : '',
                projectEnd: q.projectEnd ? new Date(q.projectEnd).toISOString().split('T')[0] : '',
                scopeOfWork: q.scopeOfWork || '',
                depositPercent: q.depositPercent || 30,
                paymentTerms: q.paymentTerms || '',
                warrantyTerms: q.warrantyTerms || '',
                cancellationPolicy: q.cancellationPolicy || '',
                notes: q.notes || '',
                termsConditions: q.termsAndConditions || ''
            });

            setLineItems(q.items.map(item => ({
                id: item._id || Math.random(),
                name: item.itemName,
                description: item.description,
                section: item.section || 'Uncategorized',
                finishBrand: item.finish || '',
                materialOrigin: item.material || '',
                size: item.size || '',
                quantity: item.quantity,
                unit: item.unit,
                rate: item.rate,
                amount: item.amount,
                image: item.image || null
            })));
            if (q.taxRate) setTaxRate(q.taxRate);
            if (q.discount) {
                setDiscount(q.discount);
                setIncludeDiscount(true);
            }
        }
        setFetching(false);
    }, [clientsRes, inventoryRes, quoteRes, clientsLoading, inventoryLoading, quoteLoading, clientsError, inventoryError, quoteError, isEdit, id]);

    // AI Auto-Fill Listener
    useEffect(() => {
        const processAIData = (data) => {
            if (!data) return;

            setFormData(prev => ({
                ...prev,
                projectName: data.projectName || prev.projectName,
                projectDescription: data.projectDescription || data.description || prev.projectDescription,
                paymentTerms: data.paymentTerms || prev.paymentTerms
            }));

            if (data.clientName && clients) {
                const matched = clients.find(c => c.name.toLowerCase().includes(data.clientName.toLowerCase()));
                if (matched) {
                    setFormData(prev => ({ ...prev, client: matched._id }));
                }
            }

            if (data.items && data.items.length > 0) {
                const newItems = data.items.map(item => ({
                    id: Math.random(),
                    name: item.name || 'AI Suggested Item',
                    description: item.description || '',
                    section: item.section || 'General',
                    finishBrand: item.finish || '',
                    materialOrigin: item.material || '',
                    size: item.size || '',
                    quantity: item.qty || 1,
                    unit: item.unit || 'SCM',
                    rate: item.rate || 0,
                    amount: (item.qty || 1) * (item.rate || 0),
                    image: null
                }));
                setLineItems(newItems);
            }
        };

        const handleAIPopulate = (e) => processAIData(e.detail);
        const pending = sessionStorage.getItem('AI_PENDING_DATA');
        if (pending) {
            const { type, data } = JSON.parse(pending);
            if (type === 'QUOTATION') {
                processAIData(data);
                sessionStorage.removeItem('AI_PENDING_DATA');
            }
        }

        window.addEventListener('AI_POPULATE_QUOTATION', handleAIPopulate);
        return () => window.removeEventListener('AI_POPULATE_QUOTATION', handleAIPopulate);
    }, [clients]);
};

import { useState } from 'react';

export const useQuotationState = () => {
    const [lineItems, setLineItems] = useState([]);
    const [taxRate, setTaxRate] = useState(18);
    const [includeTax, setIncludeTax] = useState(true);
    const [discount, setDiscount] = useState(0);
    const [includeDiscount, setIncludeDiscount] = useState(false);
    const [expandedItems, setExpandedItems] = useState({});

    const [formData, setFormData] = useState({
        client: '',
        clientPhone: '',
        quoteNumber: `QT-${new Date().getFullYear()}-${Math.floor(100 + Math.random() * 900)}`,
        date: new Date().toISOString().split('T')[0],
        validUntil: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        documentType: 'Quotation',
        projectName: '',
        projectDescription: '',
        projectStart: new Date().toISOString().split('T')[0],
        projectEnd: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        scopeOfWork: '',
        depositPercent: 30,
        paymentTerms: '',
        warrantyTerms: '',
        cancellationPolicy: '',
        notes: '',
        termsConditions: 'Payment due within 30 days. 50% deposit required to commence work.'
    });

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const updateLineItem = (id, field, value) => {
        setLineItems(prev => prev.map(item => {
            if (item.id === id) {
                const updated = { ...item, [field]: value };
                if (field === 'quantity' || field === 'rate') {
                    updated.amount = (updated.quantity || 0) * (updated.rate || 0);
                }
                return updated;
            }
            return item;
        }));
    };

    const createNewItem = () => ({
        id: Date.now() + Math.random(),
        name: '',
        description: '',
        section: 'Uncategorized',
        finishBrand: '',
        materialOrigin: '',
        size: '',
        quantity: 1,
        unit: 'SCM',
        rate: 0,
        amount: 0,
        image: null
    });

    const addLineItem = () => setLineItems(prev => [createNewItem(), ...prev]);
    const removeLineItem = (id) => setLineItems(prev => prev.filter(item => item.id !== id));

    return {
        lineItems, setLineItems,
        taxRate, setTaxRate,
        includeTax, setIncludeTax,
        discount, setDiscount,
        includeDiscount, setIncludeDiscount,
        expandedItems, setExpandedItems,
        formData, setFormData,
        handleInputChange,
        updateLineItem,
        addLineItem,
        removeLineItem
    };
};

