import { useEffect } from 'react';
import { useGetSettingsQuery } from '../../../../store/api/adminApi';
import { useGetCurrentUserQuery } from '../../../../store/api/authApi';
import { useUploadImageMutation } from '../../../../store/api/sharedApi';

export const useSettingsData = ({ 
    setSettings, setProfile, setLoading, setSaving, showToast, updateSettingsField 
}) => {

    const { data: settingsRes, isLoading: settingsLoading, error: settingsError, refetch } = useGetSettingsQuery();
    const [uploadImage] = useUploadImageMutation();

    const { data: profileRes } = useGetCurrentUserQuery();

    useEffect(() => {
        if (profileRes?.success) {
            setProfile(profileRes.data);
        }
    }, [profileRes, setProfile]);

    useEffect(() => {
        setLoading(settingsLoading);
    }, [settingsLoading, setLoading]);

    useEffect(() => {
        if (settingsError) {
            showToast('error', 'Failed to load settings');
        }
    }, [settingsError, showToast]);

    useEffect(() => {
        if (settingsRes?.success) setSettings(settingsRes.data);
    }, [settingsRes, setSettings]);

    const handleFileUpload = async (e, type) => {
        const file = e.target.files[0];
        if (!file) return;

        const formData = new FormData();
        formData.append('image', file);

        try {
            setSaving(true);
            const res = await uploadImage(formData).unwrap();
            if (res.success) {
                const url = res.data?.url || res.data?.path || res.url || res.path || res.data;
                if (type === 'logo') {
                    updateSettingsField('company', 'companyLogo', url);
                } else if (type === 'avatar') {
                    setProfile(prev => ({ ...prev, avatar: url }));
                }
                showToast('success', 'Image uploaded successfully!');
            }
        } catch (err) {
            showToast('error', 'Failed to upload image');
        } finally {
            setSaving(false);
        }
    };

    return { fetchData: refetch, handleFileUpload };
};

import React, { useState, useEffect } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import { ChevronDown, ChevronRight } from 'lucide-react';

const SidebarNav = ({ navGroups }) => {
    const location = useLocation();
    const [collapsedGroups, setCollapsedGroups] = useState({});

    // Keep groups open if they contain the active item
    useEffect(() => {
        const currentTab = new URLSearchParams(location.search).get('tab');
        const activePath = location.pathname + (currentTab ? `?tab=${currentTab}` : '');

        navGroups.forEach(group => {
            const hasActive = group.items.some(item => {
                if (item.path.includes('?tab=')) {
                    const itemTab = new URLSearchParams(item.path.split('?')[1]).get('tab');
                    return currentTab === itemTab || (!currentTab && (itemTab === 'overview' || itemTab === 'dashboard' || itemTab === 'pipeline'));
                }
                return item.path === activePath;
            });

            if (hasActive) {
                setCollapsedGroups(prev => ({ ...prev, [group.title]: false }));
            } else if (collapsedGroups[group.title] === undefined && group.title !== 'Main') {
                 setCollapsedGroups(prev => ({ ...prev, [group.title]: false }));
            }
        });
    }, [navGroups, location]);

    const toggleGroup = (title) => {
        if (title === 'Main') return;
        setCollapsedGroups(prev => ({ ...prev, [title]: !prev[title] }));
    };

    return (
        <nav className="sidebar-nav">
            {navGroups.map((group) => {
                const isCollapsed = collapsedGroups[group.title];
                return (
                    <div key={group.title} className="nav-group">
                        {group.title !== 'Main' && (
                            <div 
                                className="nav-group-header" 
                                onClick={() => toggleGroup(group.title)}
                                style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', cursor: 'pointer', paddingRight: '8px' }}
                            >
                                <h3 className="nav-group-title">{group.title}</h3>
                                {isCollapsed ? <ChevronRight size={14} color="#94a3b8" /> : <ChevronDown size={14} color="#94a3b8" />}
                            </div>
                        )}
                        {!isCollapsed && (
                            <ul className="nav-list" style={{ marginTop: group.title !== 'Main' ? '4px' : '0' }}>
                                {group.items.map((item) => (
                                    <li key={item.name} className="nav-item">
                                        <NavLink
                                            to={item.path}
                                            className={({ isActive }) => {
                                                if (item.path.includes('?tab=')) {
                                                    const currentTab = new URLSearchParams(location.search).get('tab');
                                                    const itemTab = new URLSearchParams(item.path.split('?')[1]).get('tab');
                                                    const isTabActive = currentTab === itemTab || 
                                                        (!currentTab && (itemTab === 'overview' || itemTab === 'dashboard' || itemTab === 'pipeline'));
                                                    return `nav-link ${isTabActive ? 'active' : ''}`;
                                                }
                                                return `nav-link ${isActive ? 'active' : ''}`;
                                            }}
                                        >
                                            <item.icon size={18} className="nav-icon" />
                                            <span>{item.name}</span>
                                        </NavLink>
                                    </li>
                                ))}
                            </ul>
                        )}
                    </div>
                );
            })}
        </nav>
    );
};

export default SidebarNav;

import { 
    useCreateStaffMutation, 
    useUpdateStaffMutation, 
    useDeleteStaffMutation,
    useUpdateStaffSalaryMutation,
    adminApi
} from '../../../../store/api/adminApi';
import { useDispatch } from 'react-redux';

export const useStaffActions = ({ 
    editingStaff, formData, fetchStaff, showToast, closeModal, 
    setSubmitting, setSalaryStaff, setSalaryForm, setSalaryEditMode,
    setSalaryLoading, setShowSalaryModal, setSalarySubmitting,
    setSelectedAnalytics, setAnalyticsLoading, setShowAnalytics
}) => {
    const dispatch = useDispatch();

    const [createStaff] = useCreateStaffMutation();
    const [updateStaff] = useUpdateStaffMutation();
    const [deleteStaff] = useDeleteStaffMutation();
    const [updateStaffSalary] = useUpdateStaffSalaryMutation();

    const handleSubmit = async (e) => {
        if (e) e.preventDefault();

        // Validation logic
        if (!formData.name || formData.name.trim().length < 2) { showToast('Name too short', 'error'); return; }
        if (!/^[0-9]{10}$/.test(formData.phone)) { showToast('Phone must be 10 digits', 'error'); return; }

        setSubmitting(true);
        try {
            if (editingStaff) {
                await updateStaff({ id: editingStaff._id, ...formData }).unwrap();
                await fetchStaff(); showToast('Updated!'); closeModal();
            } else {
                await createStaff(formData).unwrap();
                await fetchStaff(); showToast('Added!'); closeModal();
            }
        } catch (err) {
            showToast(err.data?.message || err.message || 'Error', 'error');
        } finally {
            setSubmitting(false);
        }
    };

    const handleViewSalary = async (staff) => {
        setSalaryStaff(null);
        setSalaryEditMode(false);
        setSalaryLoading(true);
        setShowSalaryModal(true);
        try {
            const res = await dispatch(adminApi.endpoints.getStaffSalary.initiate(staff._id)).unwrap();
            if (res.success) {
                setSalaryStaff(res.data);
                const s = res.data.salary || {};
                setSalaryForm({
                    baseSalary: s.baseSalary || '', hra: s.hra || '', travelAllowance: s.travelAllowance || '',
                    otherAllowances: s.otherAllowances || '', providentFund: s.providentFund || '',
                    taxDeduction: s.taxDeduction || '', otherDeductions: s.otherDeductions || '',
                    effectiveFrom: s.effectiveFrom ? s.effectiveFrom.split('T')[0] : '', notes: s.notes || ''
                });
            }
        } catch (err) { showToast('Failed to load salary', 'error'); }
        finally { setSalaryLoading(false); }
    };

    const handleSalarySubmit = async (e, salaryStaff, salaryForm) => {
        if (e) e.preventDefault();
        setSalarySubmitting(true);
        try {
            const res = await updateStaffSalary({ id: salaryStaff._id, ...salaryForm }).unwrap();
            if (res.success) {
                setSalaryStaff(res.data);
                setSalaryEditMode(false);
                showToast('Salary updated', 'success');
            }
        } catch (err) { showToast('Update failed', 'error'); }
        finally { setSalarySubmitting(false); }
    };

    const handleViewAnalytics = async (staff) => {
        setSelectedAnalytics(null);
        setAnalyticsLoading(true);
        setShowAnalytics(true);
        try {
            const response = await dispatch(adminApi.endpoints.getStaffAnalytics.initiate(staff._id)).unwrap();
            if (response.success) setSelectedAnalytics(response.data);
        } catch (err) { showToast('Failed to load analytics', 'error'); }
        finally { setAnalyticsLoading(false); }
    };

    const handleDelete = async (id) => {
        if (!window.confirm('Delete this staff member?')) return;
        try {
            await deleteStaff(id).unwrap();
            await fetchStaff(); showToast('Deleted');
        } catch (err) { showToast('Delete failed', 'error'); }
    };

    return {
        handleSubmit,
        handleViewSalary,
        handleSalarySubmit,
        handleViewAnalytics,
        handleDelete
    };
};

import { 
    useCreateTaskMutation,
    useUpdateTaskMutation, 
    useDeleteTaskMutation, 
    useSalesApproveTaskMutation, 
    useAdminReviewTaskMutation 
} from '../../../../store/api/adminApi';

export const useTasksActions = ({ 
    editingTask, formData, fetchTasks, showToast, closeModal, 
    setTasks, setSubmitting 
}) => {

    const [createTask] = useCreateTaskMutation();
    const [updateTask] = useUpdateTaskMutation();
    const [deleteTask] = useDeleteTaskMutation();
    const [salesApprove] = useSalesApproveTaskMutation();
    const [adminReview] = useAdminReviewTaskMutation();

    const handleSubmit = async (e) => {
        if (e) e.preventDefault();
        setSubmitting(true);
        try {
            if (editingTask) {
                await updateTask({ id: editingTask._id, ...formData }).unwrap();
                await fetchTasks();
                showToast('Task updated successfully');
                closeModal();
            } else {
                await createTask(formData).unwrap();
                await fetchTasks();
                showToast('New task assigned successfully');
                closeModal();
            }
        } catch (err) {
            showToast(err.data?.message || err.message || 'Failed to save task', 'error');
        } finally {
            setSubmitting(false);
        }
    };

    const handleStatusChange = async (taskId, newStatus) => {
        try {
            await updateTask({ id: taskId, status: newStatus }).unwrap();
            setTasks(prev => prev.map(t => t._id === taskId ? { 
                ...t, 
                status: newStatus, 
                progress: newStatus === 'Completed' ? 100 : t.progress 
            } : t));
            showToast(`Task status updated to ${newStatus}`);
        } catch (err) {
            showToast('Failed to update status', 'error');
        }
    };

    const handleProgressChange = async (taskId, newProgress) => {
        try {
            const updateData = { progress: newProgress };
            if (newProgress === 100) updateData.status = 'Completed';
            else if (newProgress > 0 && newProgress < 100) updateData.status = 'In Progress';

            await updateTask({ id: taskId, ...updateData }).unwrap();
            setTasks(prev => prev.map(t => t._id === taskId ? { ...t, ...updateData } : t));
        } catch (err) {
            showToast('Failed to update progress', 'error');
        }
    };

    const handleSalesReview = async (taskId, approved) => {
        const notes = prompt(approved ? 'Add optional sales notes:' : 'Enter reason for revision:');
        if (!approved && !notes) return;

        try {
            await salesApprove({ id: taskId, approved, salesNotes: notes || '' }).unwrap();
            setTasks(prev => prev.map(t => t._id === taskId ? { ...t, status: approved ? 'Sales Approved' : 'Revision Required' } : t));
            showToast(approved ? 'Design approved by Sales' : 'Revision requested');
        } catch (err) {
            showToast('Sales review failed', 'error');
        }
    };

    const handleAdminReview = async (taskId, approved) => {
        const notes = prompt(approved ? 'Add final approval notes (optional):' : 'Enter rejection reason (required):');
        if (!approved && !notes) return;

        try {
            await adminReview({ id: taskId, approved, rejectionReason: notes || '' }).unwrap();
            setTasks(prev => prev.map(t => t._id === taskId ? { ...t, status: approved ? 'Pushed to Procurement' : 'Admin Rejected' } : t));
            showToast(approved ? 'Pushed to Procurement successfully' : 'Design rejected and sent back');
        } catch (err) {
            showToast('Admin review failed', 'error');
        }
    };

    const handleDelete = async (id) => {
        if (!window.confirm('Are you sure you want to delete this task?')) return;
        try {
            await deleteTask(id).unwrap();
            await fetchTasks();
            showToast('Task deleted successfully');
        } catch (err) {
            showToast('Failed to delete task', 'error');
        }
    };

    return {
        handleSubmit,
        handleStatusChange,
        handleProgressChange,
        handleSalesReview,
        handleAdminReview,
        handleDelete
    };
};

import { 
    useCreateUserMutation, 
    useUpdateUserMutation, 
    useDeleteUserMutation 
} from '../../../../store/api/adminApi';

export const useUserActions = ({ 
    fetchUsers, setSubmitting, setShowModal, setEditingUser, setFormData, setUsers, users 
}) => {

    const [createUser] = useCreateUserMutation();
    const [updateUser] = useUpdateUserMutation();
    const [deleteUser] = useDeleteUserMutation();

    const handleEditClick = (user) => {
        setEditingUser(user);
        setFormData({
            fullName: user.fullName || '',
            email: user.email || '',
            phone: user.phone || '',
            role: user.role || 'Admin',
            department: user.department || 'Admin',
            password: ''
        });
        setShowModal(true);
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;

        if (name === 'role') {
            let dept = 'Admin';
            if (value.includes('Design')) dept = 'Design';
            else if (value.includes('Procurement')) dept = 'Procurement';
            else if (value.includes('Production') || value.includes('Project') || value.includes('Site')) dept = 'Production';
            else if (value.includes('Accounts')) dept = 'Accounts';
            else if (value === 'Sales') dept = 'Sales';

            setFormData(prev => ({ ...prev, role: value, department: dept }));
        } else {
            setFormData(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleSubmit = async (formData, editingUser) => {
        if (!formData.fullName || !formData.email || (!editingUser && !formData.password)) {
            alert('Name, Email and Password are required');
            return;
        }

        try {
            setSubmitting(true);
            if (editingUser) {
                await updateUser({ id: editingUser._id, ...formData }).unwrap();
            } else {
                await createUser(formData).unwrap();
            }

            alert(editingUser ? 'User updated successfully' : 'New user created successfully');
            setShowModal(false);
            fetchUsers();
            setEditingUser(null);
            setFormData({ fullName: '', email: '', phone: '', role: 'Admin', department: 'Admin', password: '' });
        } catch (err) {
            alert(err.data?.message || err.message || `Error ${editingUser ? 'updating' : 'creating'} user`);
        } finally {
            setSubmitting(false);
        }
    };

    const handleDelete = async (id) => {
        if (!window.confirm('Are you sure you want to delete this user?')) return;
        try {
            await deleteUser(id).unwrap();
            setUsers(users.filter(u => u._id !== id));
            alert('User deleted successfully');
        } catch (err) {
            alert('Failed to delete user');
        }
    };

    return { handleEditClick, handleInputChange, handleSubmit, handleDelete };
};

