                    <div className="eng-task-list">
                        {data.recentTasks.map(t => (
                            <TaskRow key={t._id} task={t} onClick={() => navigate(`/engineer/tasks/${t._id}`)} />
                        ))}
                    </div>
                )}
            </div>
        </div>
