import { useState, useEffect } from 'react';
import { 
    useGetProductionPipelineQuery, 
    useGetReplacementRequestsQuery, 
    useActionReplacementRequestMutation 
} from '../../../../store/api/productionApi';
import { useGetApprovalsQuery, useCreateApprovalMutation, useUpdateApprovalMutation } from '../../../../store/api/sharedApi';

export const useApprovals = () => {
    const [activeTab, setActiveTab] = useState('general');
    const [filterStatus, setFilterStatus] = useState('all');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [filtersOpen, setFiltersOpen] = useState(false);
    const [expandedRow, setExpandedRow] = useState(null);

    const [newRequest, setNewRequest] = useState({
        requestTitle: '', projectName: '', submittedBy: '', requestType: 'Material', value: ''
    });

    const toggleRow = (id) => setExpandedRow(expandedRow === id ? null : id);

    // Replacement requests handled via RTK Query
    const { data: staffRes, isLoading: loadingStaff, refetch: fetchStaffRequests } = useGetReplacementRequestsQuery();
    const [actionReplacementRequest] = useActionReplacementRequestMutation();

    const staffRequests = staffRes?.success ? staffRes.data : [];

    const [createApproval] = useCreateApprovalMutation();
    const [updateApproval] = useUpdateApprovalMutation();

    const { data: genRes, isLoading: localLoading } = useGetApprovalsQuery();
    const approvals = genRes?.success ? genRes.data : [];

    useEffect(() => {
        const handleOpenModal = () => setIsModalOpen(true);
        window.addEventListener('open-create-approval-modal', handleOpenModal);
        return () => window.removeEventListener('open-create-approval-modal', handleOpenModal);
    }, []);

    const filteredApprovals = (activeTab === 'general' ? approvals : staffRequests).filter(item => {
        if (filterStatus === 'all') return true;
        return item.status.toLowerCase() === filterStatus.toLowerCase();
    });

    const handleCreateRequest = async (e) => {
        e.preventDefault();
        try {
            const dataToSubmit = { ...newRequest, value: newRequest.value ? Number(newRequest.value) : 0 };
            await createApproval(dataToSubmit).unwrap();
            setIsModalOpen(false);
            setNewRequest({ requestTitle: '', projectName: '', submittedBy: '', requestType: 'Material', value: '' });
        } catch (err) {
            alert("Error creating request: " + err.message);
        }
    };

    const handleUpdateStatus = async (id, newStatus) => {
        try {
            await updateApproval({ id, status: newStatus }).unwrap();
        } catch (err) {
            alert("Error: " + err.message);
        }
    };

    const handleActionStaffRequest = async (id, status) => {
        const remarks = prompt("Enter remarks (optional):");
        try {
            await actionReplacementRequest({ requestId: id, status, adminRemarks: remarks }).unwrap();
            fetchStaffRequests();
        } catch (err) {
            alert("Error: " + (err.data?.message || err.message));
        }
    };

    return {
        activeTab, setActiveTab,
        loading: loadingStaff || localLoading, 
        error: null,
        filterStatus, setFilterStatus,
        isModalOpen, setIsModalOpen,
        filtersOpen, setFiltersOpen,
        expandedRow, toggleRow, setExpandedRow,
        newRequest, setNewRequest,
        filteredApprovals,
        handleCreateRequest,
        handleUpdateStatus,
        handleActionStaffRequest
    };
};

import { useEffect } from 'react';
import { useGetProductionReportsQuery } from '../../../../store/api/productionApi';

export const useProductionReports = () => {
    const { data, isLoading: loading, error: rawError } = useGetProductionReportsQuery();
    const reportsData = data?.success ? data.data : null;
    const error = rawError?.message ?? null;

    // Download CSV — triggered by a global event from the toolbar button
    const downloadCSV = () => {
        if (!reportsData?.projectBreakdown) return;

        const headers = ['Project Name', 'Status', 'Total Tasks', 'Completed Tasks', 'Completion Rate (%)'];
        const csvRows = [headers.join(',')];
        reportsData.projectBreakdown.forEach(proj => {
            csvRows.push([
                `"${proj.projectName}"`,
                `"${proj.status}"`,
                proj.totalTasks,
                proj.completedTasks,
                proj.completionRate,
            ].join(','));
        });

        const blob = new Blob([csvRows.join('\n')], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.setAttribute('hidden', '');
        a.setAttribute('href', url);
        a.setAttribute('download', `production_report_${new Date().toISOString().split('T')[0]}.csv`);
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    };

    useEffect(() => {
        const handleExport = () => downloadCSV();
        window.addEventListener('export-production-reports-pdf', handleExport);
        return () => window.removeEventListener('export-production-reports-pdf', handleExport);
    }, [reportsData]);

    return { reportsData, loading, error };
};

import { useState, useEffect } from 'react';
import {
    useGetHandoffProjectsQuery,
    useGetProductionStaffQuery,
    useAcceptHandoffMutation,
} from '../../../../store/api/productionApi';
import { useToast } from '../../../../models/context/ToastContext';

export const useProjectHandoff = () => {
    const { showToast } = useToast();
    const [submitting, setSubmitting] = useState({});
    const [assignments, setAssignments] = useState({});

    const { data: projectsData, isLoading: projectsLoading } = useGetHandoffProjectsQuery();
    const { data: staffData, isLoading: staffLoading } = useGetProductionStaffQuery();
    const [acceptHandoffMutation] = useAcceptHandoffMutation();

    const projects = projectsData?.data ?? [];
    const staff = staffData?.data ?? [];
    const loading = projectsLoading || staffLoading;

    // Initialise assignment slots whenever the project list updates
    useEffect(() => {
        const initial = {};
        projects.forEach(p => {
            if (!assignments[p._id]) {
                initial[p._id] = { projectEngineer: '', siteEngineer: '', siteSupervisor: '' };
            }
        });
        if (Object.keys(initial).length) {
            setAssignments(prev => ({ ...prev, ...initial }));
        }
    }, [projects.length]);

    const handleAssign = (projectId, role, userId) => {
        setAssignments(prev => ({
            ...prev,
            [projectId]: { ...prev[projectId], [role]: userId }
        }));
    };

    const handleAcceptHandoff = async (project) => {
        const projectAssignments = assignments[project._id] ?? {};
        const noAssignments = !projectAssignments.projectEngineer &&
            !projectAssignments.siteEngineer &&
            !projectAssignments.siteSupervisor;

        if (noAssignments) {
            const proceed = window.confirm("You haven't assigned any team members. Do you still want to activate this project?");
            if (!proceed) return;
        }

        try {
            setSubmitting(prev => ({ ...prev, [project._id]: true }));
            await acceptHandoffMutation({
                id: project._id,
                projectEngineer: projectAssignments.projectEngineer || null,
                siteEngineer: projectAssignments.siteEngineer || null,
                siteSupervisor: projectAssignments.siteSupervisor || null,
            }).unwrap();
            showToast('Project activated and team assigned successfully');
        } catch (err) {
            console.error('Accept handoff error:', err);
            showToast('Failed to accept handoff', 'error');
        } finally {
            setSubmitting(prev => ({ ...prev, [project._id]: false }));
        }
    };

    return {
        projects,
        loading,
        submitting,
        assignments,
        handleAssign,
        handleAcceptHandoff,
        projectEngineers: staff.filter(s => s.role === 'Project Engineer'),
        siteEngineers: staff.filter(s => s.role === 'Site Engineer'),
        siteSupervisors: staff.filter(s => s.role === 'Site Supervisor'),
    };
};

import { useState, useEffect } from 'react';
import { useToast } from '../../../../models/context/ToastContext';
import { 
    useGetEngineerProjectTasksQuery, 
    useGetProductionStaffQuery, 
    useAssignTeamMutation, 
    useCreatePMTaskMutation, 
    useAssignTaskMutation, 
    useApproveTaskMutation 
} from '../../../../store/api/productionApi';

export const useProjectTasksAssignment = (project, onProjectUpdate) => {
    const { showToast } = useToast();

    // Core states
    const [activeTab, setActiveTab] = useState('tasks');

    // Loading/Submitting states
    const [updatingTeam, setUpdatingTeam] = useState(false);
    const [creatingTask, setCreatingTask] = useState(false);
    const [actioningTaskId, setActioningTaskId] = useState(null);

    // Form states
    const [teamForm, setTeamForm] = useState({
        projectEngineer: project?.projectEngineer?._id || project?.projectEngineer || '',
        siteEngineer: project?.siteEngineer?._id || project?.siteEngineer || '',
        siteSupervisor: project?.siteSupervisor?._id || project?.siteSupervisor || ''
    });

    const [newTaskForm, setNewTaskForm] = useState({
        title: '',
        description: '',
        assignedTo: '',
        stage: 'PE', // PM | PE | SE | SS
        priority: 'Medium' // Low | Medium | High | Urgent
    });

    const { data: tasksRes, isLoading: loadingTasks, refetch: fetchTasks } = useGetEngineerProjectTasksQuery(project?._id, { skip: !project?._id });
    const { data: staffRes } = useGetProductionStaffQuery(undefined, { skip: !project?._id });
    const [assignTeam] = useAssignTeamMutation();
    const [createTask] = useCreatePMTaskMutation();
    const [assignTask] = useAssignTaskMutation();
    const [approveTask] = useApproveTaskMutation();

    const tasks = tasksRes?.success ? tasksRes.data : [];
    const staff = staffRes?.success ? staffRes.data : [];

    const getFilteredStaff = (stageValue) => {
        let assignedId = null;
        if (stageValue === 'PE') assignedId = project?.projectEngineer?._id || project?.projectEngineer;
        else if (stageValue === 'SE') assignedId = project?.siteEngineer?._id || project?.siteEngineer;
        else if (stageValue === 'SS') assignedId = project?.siteSupervisor?._id || project?.siteSupervisor;
        else if (stageValue === 'PM') assignedId = project?.projectManager?._id || project?.projectManager;

        if (assignedId) {
            const assignedIdStr = assignedId.toString();
            return staff.filter(s => s._id === assignedIdStr);
        }
        return [];
    };

    const handleUpdateTeam = async (e) => {
        e.preventDefault();
        try {
            setUpdatingTeam(true);
            await assignTeam({
                projectId: project._id,
                projectEngineer: teamForm.projectEngineer || null,
                siteEngineer: teamForm.siteEngineer || null,
                siteSupervisor: teamForm.siteSupervisor || null
            }).unwrap();

            showToast('Project team assignments updated successfully');
            if (onProjectUpdate) onProjectUpdate();
        } catch (err) {
            console.error('Update team error:', err);
            showToast(err.data?.message || err.message || 'Failed to update project team', 'error');
        } finally {
            setUpdatingTeam(false);
        }
    };

    const handleCreateTask = async (e) => {
        e.preventDefault();
        if (!newTaskForm.title.trim()) {
            showToast('Please provide a task title', 'warning');
            return;
        }

        try {
            setCreatingTask(true);
            await createTask({ ...newTaskForm, projectId: project._id }).unwrap();

            showToast('New production task created and assigned successfully');
            setNewTaskForm({ title: '', description: '', assignedTo: '', stage: 'PE', priority: 'Medium' });
            setActiveTab('tasks');
            fetchTasks();
        } catch (err) {
            console.error('Create task error:', err);
            showToast(err.data?.message || err.message || 'Failed to create task', 'error');
        } finally {
            setCreatingTask(false);
        }
    };

    const handleReassignTask = async (taskId, newAssigneeId) => {
        try {
            setActioningTaskId(taskId);
            await assignTask({ taskId, assignedTo: newAssigneeId || null }).unwrap();
            showToast('Task reassigned successfully');
            fetchTasks();
        } catch (err) {
            console.error('Reassign task error:', err);
            showToast(err.data?.message || err.message || 'Failed to reassign task', 'error');
        } finally {
            setActioningTaskId(null);
        }
    };

    const handleApproveTask = async (taskId) => {
        try {
            setActioningTaskId(taskId);
            await approveTask(taskId).unwrap();
            showToast('Task approved successfully');
            fetchTasks();
        } catch (err) {
            console.error('Approve task error:', err);
            showToast(err.data?.message || err.message || 'Failed to approve task', 'error');
        } finally {
            setActioningTaskId(null);
        }
    };

    const projectEngineers = staff.filter(s => s.role === 'Project Engineer');
    const siteEngineers = staff.filter(s => s.role === 'Site Engineer');
    const siteSupervisors = staff.filter(s => s.role === 'Site Supervisor');

    return {
        tasks, staff, loadingTasks,
        activeTab, setActiveTab,
        updatingTeam, creatingTask, actioningTaskId,
        teamForm, setTeamForm,
        newTaskForm, setNewTaskForm,
        getFilteredStaff, handleUpdateTeam, handleCreateTask,
        handleReassignTask, handleApproveTask,
        projectEngineers, siteEngineers, siteSupervisors
    };
};

import { useState, useEffect } from 'react';
