import { useState, useEffect } from 'react';
import { format } from 'date-fns';
import { 
    useGetSupervisorReportsQuery, 
    useSubmitSupervisorReportMutation 
} from '../../../../store/api/productionApi';

export const useSupervisorReports = (projects) => {
    const [submitted, setSubmitted] = useState(false);
    const [errors, setErrors] = useState({});
    const [form, setForm] = useState({
        projectId: '',
        reportDate: format(new Date(), 'yyyy-MM-dd'),
        materialReceived: '',
        materialUsed: '',
        laborCount: '',
        equipmentStatus: [{ equipmentName: '', status: 'Working' }],
        comments: ''
    });

    useEffect(() => {
        if (projects && projects.length > 0 && !form.projectId) {
            setForm(f => ({ ...f, projectId: projects[0]._id }));
        }
    }, [projects, form.projectId]);

    const { data: reportsRes } = useGetSupervisorReportsQuery(form.projectId, { skip: !form.projectId });
    const reports = reportsRes?.success ? reportsRes.data : [];

    const [submitSupervisorReport, { isLoading: submitting }] = useSubmitSupervisorReportMutation();

    const handleProjectChange = (projectId) => {
        setForm(f => ({ ...f, projectId }));
        setErrors(er => ({ ...er, projectId: undefined }));
    };

    const validate = () => {
        const e = {};
        if (!form.projectId) e.projectId = 'Select a project';
        return e;
    };

    const addEquipment = () => setForm(f => ({ ...f, equipmentStatus: [...f.equipmentStatus, { equipmentName: '', status: 'Working' }] }));

    const updateEquipment = (index, field, value) => {
        const newEq = [...form.equipmentStatus];
        newEq[index][field] = value;
        setForm(f => ({ ...f, equipmentStatus: newEq }));
    };

    const removeEquipment = (index) => {
        const newEq = form.equipmentStatus.filter((_, i) => i !== index);
        setForm(f => ({ ...f, equipmentStatus: newEq }));
    };

    const handleSubmit = async (e) => {
        if (e) e.preventDefault();
        const errs = validate();
        if (Object.keys(errs).length) { setErrors(errs); return; }

        try {
            // Clean empty equipment
            const cleanEq = form.equipmentStatus.filter(eq => eq.equipmentName.trim() !== '');
            const payload = { ...form, equipmentStatus: cleanEq };

            await submitSupervisorReport(payload).unwrap();

            setForm({ 
                ...form, 
                reportDate: format(new Date(), 'yyyy-MM-dd'), 
                materialReceived: '', 
                materialUsed: '', 
                laborCount: '', 
                equipmentStatus: [{ equipmentName: '', status: 'Working' }], 
                comments: '' 
            });
            setErrors({});
            setSubmitted(true);
            setTimeout(() => setSubmitted(false), 4000);
        } catch (error) { 
            console.error('Failed to submit supervisor report', error); 
        }
    };

    return {
        reports,
        submitting,
        submitted,
        errors, setErrors,
        form, setForm,
        handleProjectChange,
        addEquipment,
        updateEquipment,
        removeEquipment,
        handleSubmit
    };
};

import React, { useState, useEffect, useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';
import { 
    ClipboardCheck, Search, Eye, Loader, CheckCircle, 
    AlertCircle, MessageSquare, Briefcase, Calendar, X 
} from 'lucide-react';
import { useGetSalesTasksQuery, useApproveSalesTaskMutation } from '../../store/api/salesApi';
import DesignPreviewModal from './components/DesignPreviewModal';
import CustomSelect from './components/CustomSelect';
import Skeleton from './components/Skeleton';
import './css/SalesTasks.css';
import './css/SalesApprovals.css';
import { useAppSelector } from '../../store/hooks';
import { selectUser } from '../../store/slices/authSlice';

const SalesApprovals = ({}) => {
    const user = useAppSelector(selectUser);
    const [searchParams] = useSearchParams();
    const [priorityFilter, setPriorityFilter] = useState('');

    // Interactive feedback modal state
    const [actionTask, setActionTask] = useState(null); 
    const [actionType, setActionType] = useState(null); // 'approve' | 'reject'
    const [salesNotes, setSalesNotes] = useState('');
    const [submittingAction, setSubmittingAction] = useState(false);

    // Preview modal state
    const [previewTask, setPreviewTask] = useState(null);

    const searchTerm = searchParams.get('q') || '';

    const { data: tasksRes, isLoading: loading, refetch: loadTasks } = useGetSalesTasksQuery();
    const [approveSalesTask] = useApproveSalesTaskMutation();

    const tasks = tasksRes?.success ? tasksRes.data : [];

    const pendingTasks = tasks.filter(t => t.status === 'Pending Sales Review');
    const approvedCount = tasks.filter(t => t.status === 'Sales Approved').length;
    const revisionCount = tasks.filter(t => t.status === 'Revision Required').length;
    const criticalCount = pendingTasks.filter(t => t.priority === 'Critical' || t.priority === 'High').length;

    // Handle Search & Filter logic
    const filteredTasks = pendingTasks.filter(task => {
        const titleMatch = task.title?.toLowerCase().includes(searchTerm.toLowerCase());
        const projectMatch = (task.project?.projectName || task.quotation?.projectName || '')
            .toLowerCase()
            .includes(searchTerm.toLowerCase());

        const matchesSearch = titleMatch || projectMatch;
        const matchesPriority = priorityFilter ? task.priority === priorityFilter : true;

        return matchesSearch && matchesPriority;
    });

    const triggerAction = (task, type) => {
        setActionTask(task);
        setActionType(type);
        setSalesNotes('');
    };

    const handleActionSubmit = async (e) => {
        e.preventDefault();
        if (!actionTask || !actionType) return;

        if (actionType === 'reject' && !salesNotes.trim()) {
            alert('Please provide feedback notes explaining the reason for the revision request.');
            return;
        }

        try {
            setSubmittingAction(true);
            const approved = actionType === 'approve';
            const res = await approveSalesTask({ 
                id: actionTask._id, 
                approved, 
                salesNotes: salesNotes.trim() 
            }).unwrap();

            if (res.success) {
                setActionTask(null);
                setActionType(null);
                setSalesNotes('');
                loadTasks();
            } else {
                alert(res.message || 'Operation failed');
            }
        } catch (error) {
            console.error('Error reviewing design:', error);
            alert('Something went wrong. Please try again.');
        } finally {
            setSubmittingAction(false);
        }
    };

    return (
        <div className="st-tasks-container">
            <div className="st-tasks-wrapper">

                {/* ── Statistics Summary Grid (Same layout as other pages) ── */}
                <div className="st-stats-grid">
                    <div className="st-stat-card">
                        <div className="st-stat-info">
                            <span className="st-stat-label">Pending Review</span>
                            <span className="st-stat-value">
                                {loading ? <Skeleton width="40px" height="32px" /> : pendingTasks.length}
                            </span>
                        </div>
                    </div>
                    <div className="st-stat-card">
                        <div className="st-stat-info">
                            <span className="st-stat-label">High Priority</span>
                            <span className="st-stat-value">
                                {loading ? <Skeleton width="40px" height="32px" /> : criticalCount}
                            </span>
                        </div>
                    </div>
                    <div className="st-stat-card">
                        <div className="st-stat-info">
                            <span className="st-stat-label">Sales Approved</span>
                            <span className="st-stat-value">
                                {loading ? <Skeleton width="40px" height="32px" /> : approvedCount}
                            </span>
                        </div>
                    </div>
                    <div className="st-stat-card">
                        <div className="st-stat-info">
                            <span className="st-stat-label">Revisions Needed</span>
                            <span className="st-stat-value">
                                {loading ? <Skeleton width="40px" height="32px" /> : revisionCount}
                            </span>
                        </div>
                    </div>
                    <div className="st-stat-card">
                        <div className="st-stat-info">
                            <span className="st-stat-label">Action Required</span>
                            <span className="st-stat-value">
                                {loading ? <Skeleton width="40px" height="32px" /> : filteredTasks.length}
                            </span>
                        </div>
                    </div>
                </div>

                {/* ── Filter Controls (Same theme & structure) ── */}
                <div style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', marginBottom: '1.5rem' }}>
                    <CustomSelect
                        variant="filter"
                        options={[
                            { value: '', label: 'All Priorities' },
                            { value: 'Critical', label: 'Critical' },
                            { value: 'High', label: 'High' },
                            { value: 'Medium', label: 'Medium' },
                            { value: 'Low', label: 'Low' }
                        ]}
                        value={priorityFilter}
                        onChange={(e) => setPriorityFilter(e.target.value)}
                        placeholder="All Priorities"
                        name="priority"
                        searchable={false}
                    />
                </div>

                {/* ── Client Approvals Grid ── */}
                {loading ? (
                    <div className="st-tasks-grid">
                        {[...Array(6)].map((_, i) => (
                            <div key={i} className="st-task-card loading" style={{ display: 'flex', flexDirection: 'column', gap: '1rem', minHeight: '260px' }}>
                                <div className="st-task-card-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                    <Skeleton width="60%" height="24px" borderRadius="6px" />
                                    <Skeleton width="20%" height="20px" borderRadius="4px" />
                                </div>

                                <div className="st-task-card-meta" style={{ display: 'flex', gap: '1.25rem' }}>
                                    <Skeleton width="40%" height="16px" />
                                    <Skeleton width="40%" height="16px" />
                                </div>

                                <div style={{ display: 'flex', gap: '8px', alignItems: 'flex-start', background: '#f8fafc', padding: '12px', borderRadius: '12px', marginTop: '4px' }}>
                                    <Skeleton width="100%" height="32px" borderRadius="6px" />
                                </div>

                                <div className="designer-section" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', borderTop: '1px solid #f1f5f9', paddingTop: '1rem', marginTop: 'auto' }}>
                                    <Skeleton width="32px" height="32px" borderRadius="50%" />
                                    <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', flex: 1 }}>
                                        <Skeleton width="40px" height="10px" />
                                        <Skeleton width="100px" height="16px" />
                                    </div>
                                </div>

                                <div className="st-task-card-footer" style={{ display: 'flex', gap: '0.5rem', width: '100%' }}>
                                    <Skeleton width="33%" height="36px" borderRadius="8px" />
                                    <Skeleton width="33%" height="36px" borderRadius="8px" />
                                    <Skeleton width="33%" height="36px" borderRadius="8px" />
                                </div>
                            </div>
                        ))}
                    </div>
                ) : filteredTasks.length > 0 ? (
                    <div className="st-tasks-grid">
                        {filteredTasks.map(task => {
                            const designerName = task.assignedTo?.map(s => s.name).join(', ') || 'Design Team';
                            const designerInitials = designerName.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();

                            return (
                                <div key={task._id} className="st-task-card">
                                    <div className="st-task-card-header">
                                        <h3 className="st-task-title">{task.title}</h3>
                                        <span className={`st-priority-badge st-priority-${task.priority?.toLowerCase()}`}>
                                            {task.priority || 'Medium'}
                                        </span>
                                    </div>

                                    <div className="st-task-card-meta">
                                        <div className="st-meta-item">
                                            <Briefcase size={14} />
                                            <span>{task.project?.projectName || task.quotation?.projectName || 'Interior Project'}</span>
                                        </div>
                                        <div className="st-meta-item">
                                            <Calendar size={14} />
                                            <span>Deadline: {task.dueDate ? new Date(task.dueDate).toLocaleDateString() : 'N/A'}</span>
                                        </div>
                                    </div>

                                    {task.submissions?.[task.submissions.length - 1]?.designerNotes && (
                                        <div style={{ display: 'flex', gap: '8px', alignItems: 'flex-start', background: '#f8fafc', padding: '12px', borderRadius: '12px', marginTop: '4px' }}>
                                            <MessageSquare size={14} style={{ marginTop: '2px', flexShrink: 0, color: '#6366f1' }} />
                                            <p style={{ margin: 0, fontSize: '0.85rem', color: '#475569', lineHeight: '1.4' }}>
                                                {task.submissions[task.submissions.length - 1].designerNotes}
                                            </p>
                                        </div>
                                    )}

                                    <div className="designer-section" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', borderTop: '1px solid #f1f5f9', paddingTop: '1rem', marginTop: 'auto' }}>
                                        <div className="designer-avatar" style={{ width: '32px', height: '32px', borderRadius: '50%', background: '#e0e7ff', color: '#4f46e5', fontWeight: '600', fontSize: '0.75rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                            {designerInitials}
                                        </div>
                                        <div className="designer-name-details" style={{ display: 'flex', flexDirection: 'column' }}>
                                            <span style={{ fontSize: '0.7rem', color: '#94a3b8', textTransform: 'uppercase' }}>Designer</span>
                                            <span style={{ fontSize: '0.85rem', fontWeight: 600, color: '#334155' }}>{designerName}</span>
                                        </div>
                                    </div>

                                    <div className="st-task-card-footer" style={{ display: 'flex', gap: '0.5rem', width: '100%' }}>
                                        <button 
                                            className="st-btn-action approve"
                                            style={{ background: '#f1f5f9', color: '#475569' }}
                                            onClick={() => setPreviewTask(task)}
                                        >
                                            Preview
                                        </button>
                                        <button 
                                            className="st-btn-action reject"
                                            onClick={() => triggerAction(task, 'reject')}
                                        >
                                            Revise
                                        </button>
                                        <button 
                                            className="st-btn-action approve"
                                            onClick={() => triggerAction(task, 'approve')}
                                        >
                                            Approve
                                        </button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                ) : (
                    <div className="approvals-empty">
                        <div className="approvals-empty-icon">
                            <ClipboardCheck size={40} />
                        </div>
                        <h3>No Client Approvals Found</h3>
                        <p>All submitted designs have been reviewed or matched no filters. Check back later when designers upload new concepts.</p>
                    </div>
                )}

            </div>

            {/* ── CUSTOM DECISION POPUP/MODAL ── */}
            {actionTask && actionType && (
                <div className="local-feedback-overlay">
                    <form className="local-feedback-card" onSubmit={handleActionSubmit}>
                        <div className="feedback-header">
                            <h3>{actionType === 'approve' ? 'Approve Concept Design' : 'Request Design Revision'}</h3>
                            <button 
                                type="button" 
                                className="btn-close-feedback"
                                onClick={() => { setActionTask(null); setActionType(null); }}
                            >
                                <X size={18} />
                            </button>
                        </div>

                        <div className="feedback-input-group">
                            <label>
                                {actionType === 'approve' 
                                    ? 'Add optional presentation or coordination notes for the Design Manager:' 
                                    : 'Provide mandatory revision reasons or client feedback details:'}
                            </label>
                            <textarea
                                className="feedback-textarea"
                                placeholder={actionType === 'approve' 
                                    ? 'E.g., Client approved color scheme, wants to finalise wardrobe material choice...' 
                                    : 'E.g., Client rejected the current wooden layout. Please change to matte white finishes and relocate the vanity unit...'}
                                value={salesNotes}
                                onChange={(e) => setSalesNotes(e.target.value)}
                                required={actionType === 'reject'}
                            />
                        </div>

                        <div className="feedback-actions">
                            <button 
                                type="button" 
                                className="st-btn-action approve"
                                style={{ background: '#f1f5f9', color: '#475569', flex: 'none', width: '100px' }}
                                onClick={() => { setActionTask(null); setActionType(null); }}
                                disabled={submittingAction}
                            >
                                Cancel
                            </button>
                            <button 
                                type="submit" 
                                className={actionType === 'approve' ? 'st-btn-action approve' : 'st-btn-action reject'}
                                style={{ flex: 1 }}
                                disabled={submittingAction}
                            >
                                {submittingAction 
                                    ? 'Submitting...' 
                                    : actionType === 'approve' 
                                        ? 'Approve & Submit' 
                                        : 'Request Revision'}
                            </button>
                        </div>
                    </form>
                </div>
            )}

            {/* ── DESIGN PREVIEW MODAL ── */}
            {previewTask && (
                <DesignPreviewModal 
                    selectedTask={previewTask}
                    onClose={() => setPreviewTask(null)}
                />
            )}

        </div>
    );
};

export default SalesApprovals;

import React from 'react';
import { useSalesClients } from './hooks/useSalesClients';
import SalesClientsList from './components/SalesClientsList';
import SalesClientModal from './components/SalesClientModal';
import './css/SalesClients.css';

const SalesClients = ({ isOpportunities }) => {
    const {
        loading,
        submitting,
        showModal,
        formData,
        filteredClients,
        closeModal,
        handleInputChange,
        handleSubmit
    } = useSalesClients();

    return (
        <div className="sc-clients-container">
            <div className="sc-clients-wrapper">
                <SalesClientsList 
                    loading={loading} 
                    filteredClients={filteredClients} 
                />
            </div>

            <SalesClientModal
                showModal={showModal}
                closeModal={closeModal}
                handleSubmit={handleSubmit}
                formData={formData}
                handleInputChange={handleInputChange}
                submitting={submitting}
            />
        </div>
    );
};

export default SalesClients;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './css/SalesDashboard.css';

import { useSalesDashboardData } from './hooks/useSalesDashboardData';
import SalesStatsGrid from './components/SalesStatsGrid';
import SalesApprovalsCard from './components/SalesApprovalsCard';
import DesignPreviewModal from './components/DesignPreviewModal';
import SalesVisitsGallery from './components/SalesVisitsGallery';
import SalesUrgentTasks from './components/SalesUrgentTasks';
import SalesActivityFeed from './components/SalesActivityFeed';
import SalesRecentQuotations from './components/SalesRecentQuotations';
import SalesMonthlyTarget from './components/SalesMonthlyTarget';
import SalesQuickActions from './components/SalesQuickActions';
import { useAppSelector } from '../../store/hooks';
import { selectUser } from '../../store/slices/authSlice';

const SalesDashboard = ({}) => {
    const user = useAppSelector(selectUser);
    const navigate = useNavigate();

    // Custom Hook to handle all data fetching and state
    const {
        stats,
        urgentTasks,
        pendingReviews,
        recentVisits,
        recentQuotations,
        loading
    } = useSalesDashboardData(user);

    const [selectedTask, setSelectedTask] = useState(null);
    const [showViewModal, setShowViewModal] = useState(false);

    const handlePreviewTask = (task) => {
        setSelectedTask(task);
        setShowViewModal(true);
    };

    return (
        <div className="staff-dashboard">

            {/* ── Top Stats Grid ── */}
            <SalesStatsGrid 
                stats={stats} 
                pendingReviews={pendingReviews} 
                loading={loading} 
            />

            {/* ── Bento Grid Layout ── */}
            <div className="dashboard-bento">
                {/* Left Column (Main Content) */}
                <div className="bento-col">
                    <SalesMonthlyTarget loading={loading} />

                    {user?.role === 'Sales' && (
                        <SalesApprovalsCard 
                            pendingReviews={pendingReviews}
                            loading={loading}
                            navigate={navigate}
                            onPreviewTask={handlePreviewTask}
                        />
                    )}

                    <SalesVisitsGallery 
                        recentVisits={recentVisits} 
                        loading={loading} 
                        navigate={navigate} 
                    />

                    <SalesQuickActions navigate={navigate} />

                </div>

                {/* Right Column (Side Content) */}
                <div className="bento-col">

                    <SalesUrgentTasks 
                        urgentTasks={urgentTasks} 
                        loading={loading} 
                        navigate={navigate} 
                    />

                    <SalesActivityFeed 
                        recentVisits={recentVisits} 
                        urgentTasks={urgentTasks} 
                        loading={loading} 
                    />

                    <SalesRecentQuotations 
                        recentQuotations={recentQuotations} 
                        loading={loading} 
                        navigate={navigate} 
                    />

                </div>
            </div>

            {/* ── DESIGN PREVIEW MODAL ── */}
            {showViewModal && selectedTask && (
                <DesignPreviewModal 
                    selectedTask={selectedTask}
                    onClose={() => setShowViewModal(false)}
                />
            )}
        </div>
    );
};

export default SalesDashboard;

